import { defineHandler } from 'hono/factory'
import * as v from 'valibot'

export const AddUploadPartRequestSchema = v.strictObject({
  data: v.pipe(v.file(), v.description('The chunk of bytes for this Part.\n')),
})

export type AddUploadPartRequest = v.InferOutput<typeof AddUploadPartRequestSchema>

export const AdminApiKeySchema = v.pipe(
  v.object({
    object: v.pipe(
      v.literal('organization.admin_api_key'),
      v.description('The object type, which is always `organization.admin_api_key`'),
    ),
    id: v.pipe(
      v.string(),
      v.description('The identifier, which can be referenced in API endpoints'),
      v.metadata({ examples: ['key_abc'] }),
    ),
    name: v.optional(
      v.pipe(
        v.union([v.string(), v.nullable(v.null())]),
        v.description('The name of the API key'),
        v.metadata({ examples: ['Administration Key'] }),
      ),
    ),
    redacted_value: v.pipe(
      v.string(),
      v.description('The redacted value of the API key'),
      v.metadata({ examples: ['sk-admin...def'] }),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The Unix timestamp (in seconds) of when the API key was created'),
      v.metadata({ examples: [1711471533] }),
    ),
    expires_at: v.union([
      v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('The Unix timestamp (in seconds) of when the API key expires'),
        v.metadata({ examples: [1714063533] }),
      ),
      v.nullable(v.null()),
    ]),
    last_used_at: v.optional(
      v.union([
        v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description('The Unix timestamp (in seconds) of when the API key was last used'),
          v.metadata({ examples: [1711471534] }),
        ),
        v.nullable(v.null()),
      ]),
    ),
    owner: v.partial(
      v.object({
        type: v.pipe(
          v.string(),
          v.description('Always `user`'),
          v.metadata({ examples: ['user'] }),
        ),
        object: v.pipe(
          v.string(),
          v.description('The object type, which is always organization.user'),
          v.metadata({ examples: ['organization.user'] }),
        ),
        id: v.pipe(
          v.string(),
          v.description('The identifier, which can be referenced in API endpoints'),
          v.metadata({ examples: ['sa_456'] }),
        ),
        name: v.pipe(
          v.string(),
          v.description('The name of the user'),
          v.metadata({ examples: ['My Service Account'] }),
        ),
        created_at: v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description('The Unix timestamp (in seconds) of when the user was created'),
          v.metadata({ examples: [1711471533] }),
        ),
        role: v.pipe(
          v.string(),
          v.description('Always `owner`'),
          v.metadata({ examples: ['owner'] }),
        ),
      }),
    ),
  }),
  v.description('Represents an individual Admin API key in an org.'),
)

export type AdminApiKey = v.InferOutput<typeof AdminApiKeySchema>

export const AdminApiKeyCreateResponseSchema = v.intersect([
  AdminApiKeySchema,
  v.pipe(
    v.object({
      value: v.pipe(
        v.string(),
        v.description('The value of the API key. Only shown on create.'),
        v.metadata({ examples: ['sk-admin-1234abcd'] }),
      ),
    }),
    v.description(
      'The newly created admin API key. The `value` field is only returned once, when the key is created.',
    ),
  ),
])

export type AdminApiKeyCreateResponse = v.InferOutput<typeof AdminApiKeyCreateResponseSchema>

export const ApiKeyListSchema = v.object({
  object: v.pipe(v.literal('list'), v.metadata({ examples: ['list'] })),
  data: v.array(AdminApiKeySchema),
  has_more: v.pipe(v.boolean(), v.metadata({ examples: [false] })),
  first_id: v.optional(
    v.pipe(v.union([v.string(), v.nullable(v.null())]), v.metadata({ examples: ['key_abc'] })),
  ),
  last_id: v.optional(
    v.pipe(v.union([v.string(), v.nullable(v.null())]), v.metadata({ examples: ['key_xyz'] })),
  ),
})

export type ApiKeyList = v.InferOutput<typeof ApiKeyListSchema>

export const AssignedRoleDetailsSchema = v.pipe(
  v.object({
    id: v.pipe(v.string(), v.description('Identifier for the role.')),
    name: v.pipe(v.string(), v.description('Name of the role.')),
    permissions: v.pipe(
      v.array(v.string()),
      v.description('Permissions associated with the role.'),
    ),
    resource_type: v.pipe(v.string(), v.description('Resource type the role applies to.')),
    predefined_role: v.pipe(
      v.boolean(),
      v.description('Whether the role is predefined by OpenAI.'),
    ),
    description: v.pipe(
      v.union([v.string(), v.nullable(v.null())]),
      v.description('Description of the role.'),
    ),
    created_at: v.pipe(
      v.union([v.pipe(v.number(), v.integer()), v.nullable(v.null())]),
      v.description('When the role was created.'),
    ),
    updated_at: v.pipe(
      v.union([v.pipe(v.number(), v.integer()), v.nullable(v.null())]),
      v.description('When the role was last updated.'),
    ),
    created_by: v.pipe(
      v.union([v.string(), v.nullable(v.null())]),
      v.description('Identifier of the actor who created the role.'),
    ),
    created_by_user_obj: v.pipe(
      v.union([v.any(), v.nullable(v.null())]),
      v.description('User details for the actor that created the role, when available.'),
    ),
    metadata: v.pipe(
      v.union([v.any(), v.nullable(v.null())]),
      v.description('Arbitrary metadata stored on the role.'),
    ),
    assignment_sources: v.pipe(
      v.union([
        v.array(v.object({ principal_id: v.string(), principal_type: v.string() })),
        v.nullable(v.null()),
      ]),
      v.description('Principals from which the role assignment is inherited, when available.'),
    ),
  }),
  v.description(
    'Detailed information about a role assignment entry returned when listing assignments.',
  ),
)

export type AssignedRoleDetails = v.InferOutput<typeof AssignedRoleDetailsSchema>

export const AssistantToolsCodeSchema = v.object({
  type: v.pipe(
    v.literal('code_interpreter'),
    v.description('The type of tool being defined: `code_interpreter`'),
  ),
})

export type AssistantToolsCode = v.InferOutput<typeof AssistantToolsCodeSchema>

export const FileSearchRankerSchema = v.pipe(
  v.picklist(['auto', 'default_2024_08_21']),
  v.description(
    'The ranker to use for the file search. If not specified will use the `auto` ranker.',
  ),
)

export type FileSearchRanker = v.InferOutput<typeof FileSearchRankerSchema>

export const FileSearchRankingOptionsSchema = v.pipe(
  v.object({
    ranker: v.optional(FileSearchRankerSchema),
    score_threshold: v.pipe(
      v.pipe(v.number(), v.minValue(0), v.maxValue(1)),
      v.description(
        'The score threshold for the file search. All values must be a floating point number between 0 and 1.',
      ),
    ),
  }),
  v.description(
    'The ranking options for the file search. If not specified, the file search tool will use the `auto` ranker and a score_threshold of 0.\n\nSee the [file search tool documentation](https://developers.openai.com/api/docs/guides/tools-file-search#retrieval-customization) for more information.\n',
  ),
)

export type FileSearchRankingOptions = v.InferOutput<typeof FileSearchRankingOptionsSchema>

export const AssistantToolsFileSearchSchema = v.object({
  type: v.pipe(
    v.literal('file_search'),
    v.description('The type of tool being defined: `file_search`'),
  ),
  file_search: v.optional(
    v.pipe(
      v.partial(
        v.object({
          max_num_results: v.pipe(
            v.pipe(v.number(), v.integer(), v.minValue(1), v.maxValue(50)),
            v.description(
              'The maximum number of results the file search tool should output. The default is 20 for `gpt-4*` models and 5 for `gpt-3.5-turbo`. This number should be between 1 and 50 inclusive.\n\nNote that the file search tool may output fewer than `max_num_results` results. See the [file search tool documentation](https://developers.openai.com/api/docs/guides/tools-file-search#retrieval-customization) for more information.\n',
            ),
          ),
          ranking_options: FileSearchRankingOptionsSchema,
        }),
      ),
      v.description('Overrides for the file search tool.'),
    ),
  ),
})

export type AssistantToolsFileSearch = v.InferOutput<typeof AssistantToolsFileSearchSchema>

export const FunctionParametersSchema = v.pipe(
  v.any(),
  v.description(
    'The parameters the functions accepts, described as a JSON Schema object. See the [guide](https://developers.openai.com/api/docs/guides/function-calling) for examples, and the [JSON Schema reference](https://json-schema.org/understanding-json-schema/) for documentation about the format.\n\nOmitting `parameters` defines a function with an empty parameter list.',
  ),
)

export type FunctionParameters = v.InferOutput<typeof FunctionParametersSchema>

export const FunctionObjectSchema = v.object({
  description: v.optional(
    v.pipe(
      v.string(),
      v.description(
        'A description of what the function does, used by the model to choose when and how to call the function.',
      ),
    ),
  ),
  name: v.pipe(
    v.string(),
    v.description(
      'The name of the function to be called. Must be a-z, A-Z, 0-9, or contain underscores and dashes, with a maximum length of 64.',
    ),
  ),
  parameters: v.optional(FunctionParametersSchema),
  strict: v.optional(
    v.union([
      v.pipe(
        v.optional(v.boolean(), false),
        v.description(
          'Whether to enable strict schema adherence when generating the function call. If set to true, the model will follow the exact schema defined in the `parameters` field. Only a subset of JSON Schema is supported when `strict` is `true`. Learn more about Structured Outputs in the [function calling guide](https://developers.openai.com/api/docs/guides/function-calling).',
        ),
      ),
      v.nullable(v.null()),
    ]),
  ),
})

export type FunctionObject = v.InferOutput<typeof FunctionObjectSchema>

export const AssistantToolsFunctionSchema = v.object({
  type: v.pipe(v.literal('function'), v.description('The type of tool being defined: `function`')),
  function: FunctionObjectSchema,
})

export type AssistantToolsFunction = v.InferOutput<typeof AssistantToolsFunctionSchema>

export const MetadataSchema = v.union([
  v.pipe(
    v.record(v.string(), v.string()),
    v.description(
      'Set of 16 key-value pairs that can be attached to an object. This can be\nuseful for storing additional information about the object in a structured\nformat, and querying for objects via API or the dashboard.\n\nKeys are strings with a maximum length of 64 characters. Values are strings\nwith a maximum length of 512 characters.\n',
    ),
  ),
  v.nullable(v.null()),
])

export type Metadata = v.InferOutput<typeof MetadataSchema>

export const ResponseFormatTextSchema = v.pipe(
  v.object({
    type: v.pipe(
      v.literal('text'),
      v.description('The type of response format being defined. Always `text`.'),
    ),
  }),
  v.description('Default response format. Used to generate text responses.\n'),
)

export type ResponseFormatText = v.InferOutput<typeof ResponseFormatTextSchema>

export const ResponseFormatJsonObjectSchema = v.pipe(
  v.object({
    type: v.pipe(
      v.literal('json_object'),
      v.description('The type of response format being defined. Always `json_object`.'),
    ),
  }),
  v.description(
    'JSON object response format. An older method of generating JSON responses.\nUsing `json_schema` is recommended for models that support it. Note that the\nmodel will not generate JSON without a system or user message instructing it\nto do so.\n',
  ),
)

export type ResponseFormatJsonObject = v.InferOutput<typeof ResponseFormatJsonObjectSchema>

export const ResponseFormatJsonSchemaSchemaSchema = v.pipe(
  v.any(),
  v.description(
    'The schema for the response format, described as a JSON Schema object.\nLearn how to build JSON schemas [here](https://json-schema.org/).\n',
  ),
)

export type ResponseFormatJsonSchemaSchema = v.InferOutput<
  typeof ResponseFormatJsonSchemaSchemaSchema
>

export const ResponseFormatJsonSchemaSchema = v.pipe(
  v.object({
    type: v.pipe(
      v.literal('json_schema'),
      v.description('The type of response format being defined. Always `json_schema`.'),
    ),
    json_schema: v.pipe(
      v.object({
        description: v.optional(
          v.pipe(
            v.string(),
            v.description(
              'A description of what the response format is for, used by the model to\ndetermine how to respond in the format.\n',
            ),
          ),
        ),
        name: v.pipe(
          v.string(),
          v.description(
            'The name of the response format. Must be a-z, A-Z, 0-9, or contain\nunderscores and dashes, with a maximum length of 64.\n',
          ),
        ),
        schema: v.optional(ResponseFormatJsonSchemaSchemaSchema),
        strict: v.optional(
          v.union([
            v.pipe(
              v.optional(v.boolean(), false),
              v.description(
                'Whether to enable strict schema adherence when generating the output.\nIf set to true, the model will always follow the exact schema defined\nin the `schema` field. Only a subset of JSON Schema is supported when\n`strict` is `true`. To learn more, read the [Structured Outputs\nguide](https://developers.openai.com/api/docs/guides/structured-outputs).\n',
              ),
            ),
            v.nullable(v.null()),
          ]),
        ),
      }),
      v.description('Structured Outputs configuration options, including a JSON Schema.\n'),
    ),
  }),
  v.description(
    'JSON Schema response format. Used to generate structured JSON responses.\nLearn more about [Structured Outputs](https://developers.openai.com/api/docs/guides/structured-outputs).\n',
  ),
)

export type ResponseFormatJsonSchema = v.InferOutput<typeof ResponseFormatJsonSchemaSchema>

export const AssistantsApiResponseFormatOptionSchema = v.pipe(
  v.union([
    v.pipe(v.literal('auto'), v.description('`auto` is the default value\n')),
    ResponseFormatTextSchema,
    ResponseFormatJsonObjectSchema,
    ResponseFormatJsonSchemaSchema,
  ]),
  v.description(
    'Specifies the format that the model must output. Compatible with [GPT-4o](https://developers.openai.com/api/docs/models/gpt-4o), [GPT-4 Turbo](https://developers.openai.com/api/docs/models/gpt-4-turbo), and all GPT-3.5 Turbo models since `gpt-3.5-turbo-1106`.\n\nSetting to `{ "type": "json_schema", "json_schema": {...} }` enables Structured Outputs which ensures the model will match your supplied JSON schema. Learn more in the [Structured Outputs guide](https://developers.openai.com/api/docs/guides/structured-outputs).\n\nSetting to `{ "type": "json_object" }` enables JSON mode, which ensures the message the model generates is valid JSON.\n\n**Important:** when using JSON mode, you **must** also instruct the model to produce JSON yourself via a system or user message. Without this, the model may generate an unending stream of whitespace until the generation reaches the token limit, resulting in a long-running and seemingly "stuck" request. Also note that the message content may be partially cut off if `finish_reason="length"`, which indicates the generation exceeded `max_tokens` or the conversation exceeded the max context length.\n',
  ),
)

export type AssistantsApiResponseFormatOption = v.InferOutput<
  typeof AssistantsApiResponseFormatOptionSchema
>

export const AssistantObjectSchema = v.pipe(
  v.object({
    id: v.pipe(
      v.string(),
      v.description('The identifier, which can be referenced in API endpoints.'),
    ),
    object: v.pipe(
      v.literal('assistant'),
      v.description('The object type, which is always `assistant`.'),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The Unix timestamp (in seconds) for when the assistant was created.'),
    ),
    name: v.union([
      v.pipe(
        v.pipe(v.string(), v.maxCodePoints(256)),
        v.description('The name of the assistant. The maximum length is 256 characters.\n'),
      ),
      v.nullable(v.null()),
    ]),
    description: v.union([
      v.pipe(
        v.pipe(v.string(), v.maxCodePoints(512)),
        v.description('The description of the assistant. The maximum length is 512 characters.\n'),
      ),
      v.nullable(v.null()),
    ]),
    model: v.pipe(
      v.string(),
      v.description(
        'ID of the model to use. You can use the [List models](https://developers.openai.com/api/reference/resources/models/methods/list) API to see all of your available models, or see our [Model overview](https://developers.openai.com/api/docs/models) for descriptions of them.\n',
      ),
    ),
    instructions: v.union([
      v.pipe(
        v.pipe(v.string(), v.maxCodePoints(256000)),
        v.description(
          'The system instructions that the assistant uses. The maximum length is 256,000 characters.\n',
        ),
      ),
      v.nullable(v.null()),
    ]),
    tools: v.pipe(
      v.optional(
        v.pipe(
          v.array(
            v.union([
              AssistantToolsCodeSchema,
              AssistantToolsFileSearchSchema,
              AssistantToolsFunctionSchema,
            ]),
          ),
          v.maxLength(128),
        ),
        [],
      ),
      v.description(
        'A list of tool enabled on the assistant. There can be a maximum of 128 tools per assistant. Tools can be of types `code_interpreter`, `file_search`, or `function`.\n',
      ),
    ),
    tool_resources: v.optional(
      v.union([
        v.pipe(
          v.partial(
            v.object({
              code_interpreter: v.object({
                file_ids: v.pipe(
                  v.optional(v.pipe(v.array(v.string()), v.maxLength(20)), []),
                  v.description(
                    'A list of [file](https://developers.openai.com/api/reference/resources/files) IDs made available to the `code_interpreter`` tool. There can be a maximum of 20 files associated with the tool.\n',
                  ),
                ),
              }),
              file_search: v.partial(
                v.object({
                  vector_store_ids: v.pipe(
                    v.pipe(v.array(v.string()), v.maxLength(1)),
                    v.description(
                      'The ID of the [vector store](https://developers.openai.com/api/reference/resources/vector_stores) attached to this assistant. There can be a maximum of 1 vector store attached to the assistant.\n',
                    ),
                  ),
                }),
              ),
            }),
          ),
          v.description(
            "A set of resources that are used by the assistant's tools. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n",
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    metadata: MetadataSchema,
    temperature: v.optional(
      v.union([
        v.pipe(
          v.optional(v.pipe(v.number(), v.minValue(0), v.maxValue(2)), 1),
          v.description(
            'What sampling temperature to use, between 0 and 2. Higher values like 0.8 will make the output more random, while lower values like 0.2 will make it more focused and deterministic.\n',
          ),
          v.metadata({ examples: [1] }),
        ),
        v.nullable(v.null()),
      ]),
    ),
    top_p: v.optional(
      v.union([
        v.pipe(
          v.optional(v.pipe(v.number(), v.minValue(0), v.maxValue(1)), 1),
          v.description(
            'An alternative to sampling with temperature, called nucleus sampling, where the model considers the results of the tokens with top_p probability mass. So 0.1 means only the tokens comprising the top 10% probability mass are considered.\n\nWe generally recommend altering this or temperature but not both.\n',
          ),
          v.metadata({ examples: [1] }),
        ),
        v.nullable(v.null()),
      ]),
    ),
    response_format: v.optional(
      v.union([AssistantsApiResponseFormatOptionSchema, v.nullable(v.null())]),
    ),
  }),
  v.description('Represents an `assistant` that can call the model and use tools.'),
  v.metadata({ deprecated: true }),
)

export type AssistantObject = v.InferOutput<typeof AssistantObjectSchema>

export const ThreadObjectSchema = v.pipe(
  v.object({
    id: v.pipe(
      v.string(),
      v.description('The identifier, which can be referenced in API endpoints.'),
    ),
    object: v.pipe(
      v.literal('thread'),
      v.description('The object type, which is always `thread`.'),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The Unix timestamp (in seconds) for when the thread was created.'),
    ),
    tool_resources: v.union([
      v.pipe(
        v.partial(
          v.object({
            code_interpreter: v.object({
              file_ids: v.pipe(
                v.optional(v.pipe(v.array(v.string()), v.maxLength(20)), []),
                v.description(
                  'A list of [file](https://developers.openai.com/api/reference/resources/files) IDs made available to the `code_interpreter` tool. There can be a maximum of 20 files associated with the tool.\n',
                ),
              ),
            }),
            file_search: v.partial(
              v.object({
                vector_store_ids: v.pipe(
                  v.pipe(v.array(v.string()), v.maxLength(1)),
                  v.description(
                    'The [vector store](https://developers.openai.com/api/reference/resources/vector_stores) attached to this thread. There can be a maximum of 1 vector store attached to the thread.\n',
                  ),
                ),
              }),
            ),
          }),
        ),
        v.description(
          "A set of resources that are made available to the assistant's tools in this thread. The resources are specific to the type of tool. For example, the `code_interpreter` tool requires a list of file IDs, while the `file_search` tool requires a list of vector store IDs.\n",
        ),
      ),
      v.nullable(v.null()),
    ]),
    metadata: MetadataSchema,
  }),
  v.description(
    'Represents a thread that contains [messages](https://developers.openai.com/api/docs/assistants/migration).',
  ),
)

export type ThreadObject = v.InferOutput<typeof ThreadObjectSchema>

export const ThreadStreamEventSchema = v.union([
  v.pipe(
    v.object({
      enabled: v.optional(
        v.pipe(v.boolean(), v.description('Whether to enable input audio transcription.')),
      ),
      event: v.literal('thread.created'),
      data: ThreadObjectSchema,
    }),
    v.description(
      'Occurs when a new [thread](https://developers.openai.com/api/docs/assistants/migration) is created.',
    ),
  ),
])

export type ThreadStreamEvent = v.InferOutput<typeof ThreadStreamEventSchema>

export const RunToolCallObjectSchema = v.pipe(
  v.object({
    id: v.pipe(
      v.string(),
      v.description(
        'The ID of the tool call. This ID must be referenced when you submit the tool outputs in using the [Submit tool outputs to run](https://developers.openai.com/api/docs/assistants/migration) endpoint.',
      ),
    ),
    type: v.pipe(
      v.literal('function'),
      v.description(
        'The type of tool call the output is required for. For now, this is always `function`.',
      ),
    ),
    function: v.pipe(
      v.object({
        name: v.pipe(v.string(), v.description('The name of the function.')),
        arguments: v.pipe(
          v.string(),
          v.description('The arguments that the model expects you to pass to the function.'),
        ),
      }),
      v.description('The function definition.'),
    ),
  }),
  v.description('Tool call objects'),
)

export type RunToolCallObject = v.InferOutput<typeof RunToolCallObjectSchema>

export const RunCompletionUsageSchema = v.union([
  v.pipe(
    v.object({
      completion_tokens: v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('Number of completion tokens used over the course of the run.'),
      ),
      prompt_tokens: v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('Number of prompt tokens used over the course of the run.'),
      ),
      total_tokens: v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('Total number of tokens used (prompt + completion).'),
      ),
    }),
    v.description(
      'Usage statistics related to the run. This value will be `null` if the run is not in a terminal state (i.e. `in_progress`, `queued`, etc.).',
    ),
  ),
  v.nullable(v.null()),
])

export type RunCompletionUsage = v.InferOutput<typeof RunCompletionUsageSchema>

export const TruncationObjectSchema = v.pipe(
  v.object({
    type: v.pipe(
      v.picklist(['auto', 'last_messages']),
      v.description(
        'The truncation strategy to use for the thread. The default is `auto`. If set to `last_messages`, the thread will be truncated to the n most recent messages in the thread. When set to `auto`, messages in the middle of the thread will be dropped to fit the context length of the model, `max_prompt_tokens`.',
      ),
    ),
    last_messages: v.optional(
      v.union([
        v.pipe(
          v.pipe(v.number(), v.integer(), v.minValue(1)),
          v.description(
            'The number of most recent messages from the thread when constructing the context for the run.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
  }),
  v.description(
    'Controls for how a thread will be truncated prior to the run. Use this to control the initial context window of the run.',
  ),
)

export type TruncationObject = v.InferOutput<typeof TruncationObjectSchema>

export const AssistantsNamedToolChoiceSchema = v.pipe(
  v.object({
    type: v.pipe(
      v.picklist(['function', 'code_interpreter', 'file_search']),
      v.description('The type of the tool. If type is `function`, the function name must be set'),
    ),
    function: v.optional(
      v.object({ name: v.pipe(v.string(), v.description('The name of the function to call.')) }),
    ),
  }),
  v.description(
    'Specifies a tool the model should use. Use to force the model to call a specific tool.',
  ),
)

export type AssistantsNamedToolChoice = v.InferOutput<typeof AssistantsNamedToolChoiceSchema>

export const AssistantsApiToolChoiceOptionSchema = v.pipe(
  v.union([
    v.pipe(
      v.picklist(['none', 'auto', 'required']),
      v.description(
        '`none` means the model will not call any tools and instead generates a message. `auto` means the model can pick between generating a message or calling one or more tools. `required` means the model must call one or more tools before responding to the user.\n',
      ),
    ),
    AssistantsNamedToolChoiceSchema,
  ]),
  v.description(
    'Controls which (if any) tool is called by the model.\n`none` means the model will not call any tools and instead generates a message.\n`auto` is the default value and means the model can pick between generating a message or calling one or more tools.\n`required` means the model must call one or more tools before responding to the user.\nSpecifying a particular tool like `{"type": "file_search"}` or `{"type": "function", "function": {"name": "my_function"}}` forces the model to call that tool.\n',
  ),
)

export type AssistantsApiToolChoiceOption = v.InferOutput<
  typeof AssistantsApiToolChoiceOptionSchema
>

export const ParallelToolCallsSchema = v.pipe(
  v.optional(v.boolean(), true),
  v.description(
    'Whether to enable [parallel function calling](https://developers.openai.com/api/docs/guides/function-calling#parallel-function-calling) during tool use.',
  ),
)

export type ParallelToolCalls = v.InferOutput<typeof ParallelToolCallsSchema>

export const RunObjectSchema = v.pipe(
  v.object({
    id: v.pipe(
      v.string(),
      v.description('The identifier, which can be referenced in API endpoints.'),
    ),
    object: v.pipe(
      v.literal('thread.run'),
      v.description('The object type, which is always `thread.run`.'),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The Unix timestamp (in seconds) for when the run was created.'),
    ),
    thread_id: v.pipe(
      v.string(),
      v.description(
        'The ID of the [thread](https://developers.openai.com/api/docs/assistants/migration) that was executed on as a part of this run.',
      ),
    ),
    assistant_id: v.pipe(
      v.string(),
      v.description(
        'The ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for execution of this run.',
      ),
    ),
    status: v.pipe(
      v.picklist([
        'queued',
        'in_progress',
        'requires_action',
        'cancelling',
        'cancelled',
        'failed',
        'completed',
        'incomplete',
        'expired',
      ]),
      v.description(
        'The status of the run, which can be either `queued`, `in_progress`, `requires_action`, `cancelling`, `cancelled`, `failed`, `completed`, `incomplete`, or `expired`.',
      ),
    ),
    required_action: v.pipe(
      v.nullable(
        v.object({
          type: v.pipe(
            v.literal('submit_tool_outputs'),
            v.description('For now, this is always `submit_tool_outputs`.'),
          ),
          submit_tool_outputs: v.pipe(
            v.object({
              tool_calls: v.pipe(
                v.array(RunToolCallObjectSchema),
                v.description('A list of the relevant tool calls.'),
              ),
            }),
            v.description('Details on the tool outputs needed for this run to continue.'),
          ),
        }),
      ),
      v.description(
        'Details on the action required to continue the run. Will be `null` if no action is required.',
      ),
    ),
    last_error: v.pipe(
      v.nullable(
        v.object({
          code: v.pipe(
            v.picklist(['server_error', 'rate_limit_exceeded', 'invalid_prompt']),
            v.description('One of `server_error`, `rate_limit_exceeded`, or `invalid_prompt`.'),
          ),
          message: v.pipe(v.string(), v.description('A human-readable description of the error.')),
        }),
      ),
      v.description(
        'The last error associated with this run. Will be `null` if there are no errors.',
      ),
    ),
    expires_at: v.pipe(
      v.nullable(v.pipe(v.number(), v.integer())),
      v.description('The Unix timestamp (in seconds) for when the run will expire.'),
    ),
    started_at: v.pipe(
      v.nullable(v.pipe(v.number(), v.integer())),
      v.description('The Unix timestamp (in seconds) for when the run was started.'),
    ),
    cancelled_at: v.pipe(
      v.nullable(v.pipe(v.number(), v.integer())),
      v.description('The Unix timestamp (in seconds) for when the run was cancelled.'),
    ),
    failed_at: v.pipe(
      v.nullable(v.pipe(v.number(), v.integer())),
      v.description('The Unix timestamp (in seconds) for when the run failed.'),
    ),
    completed_at: v.pipe(
      v.nullable(v.pipe(v.number(), v.integer())),
      v.description('The Unix timestamp (in seconds) for when the run was completed.'),
    ),
    incomplete_details: v.pipe(
      v.nullable(
        v.partial(
          v.object({
            reason: v.pipe(
              v.picklist(['max_completion_tokens', 'max_prompt_tokens']),
              v.description(
                'The reason why the run is incomplete. This will point to which specific token limit was reached over the course of the run.',
              ),
            ),
          }),
        ),
      ),
      v.description(
        'Details on why the run is incomplete. Will be `null` if the run is not incomplete.',
      ),
    ),
    model: v.pipe(
      v.string(),
      v.description(
        'The model that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
      ),
    ),
    instructions: v.pipe(
      v.string(),
      v.description(
        'The instructions that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
      ),
    ),
    tools: v.pipe(
      v.optional(
        v.pipe(
          v.array(
            v.union([
              AssistantToolsCodeSchema,
              AssistantToolsFileSearchSchema,
              AssistantToolsFunctionSchema,
            ]),
          ),
          v.maxLength(20),
        ),
        [],
      ),
      v.description(
        'The list of tools that the [assistant](https://developers.openai.com/api/docs/assistants/migration) used for this run.',
      ),
    ),
    metadata: MetadataSchema,
    usage: RunCompletionUsageSchema,
    temperature: v.optional(
      v.pipe(
        v.nullable(v.number()),
        v.description('The sampling temperature used for this run. If not set, defaults to 1.'),
      ),
    ),
    top_p: v.optional(
      v.pipe(
        v.nullable(v.number()),
        v.description('The nucleus sampling value used for this run. If not set, defaults to 1.'),
      ),
    ),
    max_prompt_tokens: v.pipe(
      v.nullable(v.pipe(v.number(), v.integer(), v.minValue(256))),
      v.description(
        'The maximum number of prompt tokens specified to have been used over the course of the run.\n',
      ),
    ),
    max_completion_tokens: v.pipe(
      v.nullable(v.pipe(v.number(), v.integer(), v.minValue(256))),
      v.description(
        'The maximum number of completion tokens specified to have been used over the course of the run.\n',
      ),
    ),
    truncation_strategy: v.union([TruncationObjectSchema, v.nullable(v.null())]),
    tool_choice: v.union([AssistantsApiToolChoiceOptionSchema, v.nullable(v.null())]),
    parallel_tool_calls: ParallelToolCallsSchema,
    response_format: v.union([AssistantsApiResponseFormatOptionSchema, v.nullable(v.null())]),
  }),
  v.description(
    'Represents an execution run on a [thread](https://developers.openai.com/api/docs/assistants/migration).',
  ),
)

export type RunObject = v.InferOutput<typeof RunObjectSchema>

export const RunStreamEventSchema = v.union([
  v.pipe(
    v.object({ event: v.literal('thread.run.created'), data: RunObjectSchema }),
    v.description(
      'Occurs when a new [run](https://developers.openai.com/api/docs/assistants/migration) is created.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.queued'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) moves to a `queued` status.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.in_progress'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) moves to an `in_progress` status.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.requires_action'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) moves to a `requires_action` status.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.completed'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) is completed.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.incomplete'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) ends with status `incomplete`.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.failed'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) fails.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.cancelling'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) moves to a `cancelling` status.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.cancelled'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) is cancelled.',
    ),
  ),
  v.pipe(
    v.object({ event: v.literal('thread.run.expired'), data: RunObjectSchema }),
    v.description(
      'Occurs when a [run](https://developers.openai.com/api/docs/assistants/migration) expires.',
    ),
  ),
])

export type RunStreamEvent = v.InferOutput<typeof RunStreamEventSchema>

