export const RunStepObjectSchema = v.pipe(
  v.object({
    id: v.pipe(
      v.string(),
      v.description('The identifier of the run step, which can be referenced in API endpoints.'),
    ),
    object: v.pipe(
      v.literal('thread.run.step'),
      v.description('The object type, which is always `thread.run.step`.'),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The Unix timestamp (in seconds) for when the run step was created.'),
    ),
    assistant_id: v.pipe(
      v.string(),
      v.description(
        'The ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) associated with the run step.',
      ),
    ),
    thread_id: v.pipe(
      v.string(),
      v.description(
        'The ID of the [thread](https://developers.openai.com/api/docs/assistants/migration) that was run.',
      ),
    ),
    run_id: v.pipe(
      v.string(),
      v.description(
        'The ID of the [run](https://developers.openai.com/api/docs/assistants/migration) that this run step is a part of.',
      ),
    ),
    type: v.pipe(
      v.picklist(['message_creation', 'tool_calls']),
      v.description(
        'The type of run step, which can be either `message_creation` or `tool_calls`.',
      ),
    ),
    status: v.pipe(
      v.picklist(['in_progress', 'cancelled', 'failed', 'completed', 'expired']),
      v.description(
        'The status of the run step, which can be either `in_progress`, `cancelled`, `failed`, `completed`, or `expired`.',
      ),
    ),
    step_details: v.pipe(
      v.union([RunStepDetailsMessageCreationObjectSchema, RunStepDetailsToolCallsObjectSchema]),
      v.description('The details of the run step.'),
    ),
    last_error: v.union([
      v.pipe(
        v.object({
          code: v.pipe(
            v.picklist(['server_error', 'rate_limit_exceeded']),
            v.description('One of `server_error` or `rate_limit_exceeded`.'),
          ),
          message: v.pipe(v.string(), v.description('A human-readable description of the error.')),
        }),
        v.description(
          'The last error associated with this run step. Will be `null` if there are no errors.',
        ),
      ),
      v.nullable(v.null()),
    ]),
    expired_at: v.union([
      v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description(
          'The Unix timestamp (in seconds) for when the run step expired. A step is considered expired if the parent run is expired.',
        ),
      ),
      v.nullable(v.null()),
    ]),
    cancelled_at: v.union([
      v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('The Unix timestamp (in seconds) for when the run step was cancelled.'),
      ),
      v.nullable(v.null()),
    ]),
    failed_at: v.union([
      v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('The Unix timestamp (in seconds) for when the run step failed.'),
      ),
      v.nullable(v.null()),
    ]),
    completed_at: v.union([
      v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('The Unix timestamp (in seconds) for when the run step completed.'),
      ),
      v.nullable(v.null()),
    ]),
    metadata: MetadataSchema,
    usage: RunStepCompletionUsageSchema,
  }),
  v.description('Represents a step in execution of a run.\n'),
)

export type RunStepObject = v.InferOutput<typeof RunStepObjectSchema>

