export const MessageObjectSchema = v.pipe(
  v.object({
    id: v.pipe(
      v.string(),
      v.description('The identifier, which can be referenced in API endpoints.'),
    ),
    object: v.pipe(
      v.literal('thread.message'),
      v.description('The object type, which is always `thread.message`.'),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The Unix timestamp (in seconds) for when the message was created.'),
    ),
    thread_id: v.pipe(
      v.string(),
      v.description(
        'The [thread](https://developers.openai.com/api/docs/assistants/migration) ID that this message belongs to.',
      ),
    ),
    status: v.pipe(
      v.picklist(['in_progress', 'incomplete', 'completed']),
      v.description(
        'The status of the message, which can be either `in_progress`, `incomplete`, or `completed`.',
      ),
    ),
    incomplete_details: v.union([
      v.pipe(
        v.object({
          reason: v.pipe(
            v.picklist([
              'content_filter',
              'max_tokens',
              'run_cancelled',
              'run_expired',
              'run_failed',
            ]),
            v.description('The reason the message is incomplete.'),
          ),
        }),
        v.description('On an incomplete message, details about why the message is incomplete.'),
      ),
      v.nullable(v.null()),
    ]),
    completed_at: v.union([
      v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('The Unix timestamp (in seconds) for when the message was completed.'),
      ),
      v.nullable(v.null()),
    ]),
    incomplete_at: v.union([
      v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description(
          'The Unix timestamp (in seconds) for when the message was marked as incomplete.',
        ),
      ),
      v.nullable(v.null()),
    ]),
    role: v.pipe(
      v.picklist(['user', 'assistant']),
      v.description('The entity that produced the message. One of `user` or `assistant`.'),
    ),
    content: v.pipe(
      v.array(
        v.union([
          MessageContentImageFileObjectSchema,
          MessageContentImageUrlObjectSchema,
          MessageContentTextObjectSchema,
          MessageContentRefusalObjectSchema,
        ]),
      ),
      v.description('The content of the message in array of text and/or images.'),
    ),
    assistant_id: v.union([
      v.pipe(
        v.string(),
        v.description(
          'If applicable, the ID of the [assistant](https://developers.openai.com/api/docs/assistants/migration) that authored this message.',
        ),
      ),
      v.nullable(v.null()),
    ]),
    run_id: v.union([
      v.pipe(
        v.string(),
        v.description(
          'The ID of the [run](https://developers.openai.com/api/docs/assistants/migration) associated with the creation of this message. Value is `null` when messages are created manually using the create message or create thread endpoints.',
        ),
      ),
      v.nullable(v.null()),
    ]),
    attachments: v.union([
      v.pipe(
        v.array(
          v.partial(
            v.object({
              file_id: v.pipe(
                v.string(),
                v.description('The ID of the file to attach to the message.'),
              ),
              tools: v.pipe(
                v.array(
                  v.union([AssistantToolsCodeSchema, AssistantToolsFileSearchTypeOnlySchema]),
                ),
                v.description('The tools to add this file to.'),
              ),
            }),
          ),
        ),
        v.description('A list of files attached to the message, and the tools they were added to.'),
      ),
      v.nullable(v.null()),
    ]),
    metadata: MetadataSchema,
  }),
  v.description(
    'Represents a message within a [thread](https://developers.openai.com/api/docs/assistants/migration).',
  ),
)

export type MessageObject = v.InferOutput<typeof MessageObjectSchema>

