export const MisalignmentErrorDetailsResourceSchema = v.partial(
  v.object({
    review_target: v.union([
      v.pipe(
        v.pipe(v.string(), v.regex(/^[A-Za-z0-9._~:-]+$/), v.minCodePoints(1), v.maxCodePoints(96)),
        v.description(
          'An opaque target for explicitly continuing this review, or null when unavailable.',
        ),
        v.check((input) => !v.safeParse(v.any(), input).success),
      ),
      v.nullable(v.null()),
    ]),
    error_type: v.pipe(
      MisalignmentErrorTypeSchema,
      v.description('An optional classification; clients must accept additional values.'),
    ),
    detailed_explanation: v.pipe(
      v.string(),
      v.description('The public explanation for this block.'),
    ),
    steer: v.pipe(
      MisalignmentSteerSchema,
      v.description('An optional public continuation instruction.'),
    ),
  }),
)

