export const AudioTranscriptionSchema = v.partial(
  v.object({
    model: v.pipe(
      v.union([
        v.string(),
        v.picklist([
          'whisper-1',
          'gpt-transcribe',
          'gpt-live-transcribe',
          'gpt-4o-mini-transcribe',
          'gpt-4o-mini-transcribe-2025-12-15',
          'gpt-4o-transcribe',
          'gpt-4o-transcribe-diarize',
          'gpt-realtime-whisper',
        ]),
      ]),
      v.description(
        'The model to use for transcription. Current options are `whisper-1`, `gpt-transcribe`, `gpt-live-transcribe`, `gpt-4o-mini-transcribe`, `gpt-4o-mini-transcribe-2025-12-15`, `gpt-4o-transcribe`, `gpt-4o-transcribe-diarize`, and `gpt-realtime-whisper`. Use `gpt-4o-transcribe-diarize` when you need diarization with speaker labels.\n',
      ),
    ),
    language: v.pipe(
      v.string(),
      v.description(
        'The language of the input audio. Supplying the input language in\n[ISO-639-1](https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes) (e.g. `en`) format\nwill improve accuracy and latency.\n',
      ),
    ),
    languages: v.pipe(
      v.pipe(v.array(v.string()), v.minLength(1)),
      v.description(
        'Possible languages of the input audio, in [ISO-639-1](https://en.wikipedia.org/wiki/List_of_ISO_639-1_codes) format. Supported by `gpt-transcribe` and `gpt-live-transcribe`.\n',
      ),
    ),
    keywords: v.pipe(
      v.array(v.string()),
      v.description(
        'Words or phrases to guide transcription of the input audio. Supported by `gpt-transcribe` and `gpt-live-transcribe`.\n',
      ),
    ),
    prompt: v.pipe(
      v.string(),
      v.description(
        'An optional text to guide the model\'s style or continue a previous audio\nsegment.\nFor `whisper-1`, the [prompt is a list of keywords](https://developers.openai.com/api/docs/guides/speech-to-text#prompting).\nFor `gpt-4o-transcribe` models (excluding `gpt-4o-transcribe-diarize`), the prompt is a free text string, for example "expect words related to technology".\nPrompt is not supported with `gpt-realtime-whisper` in GA Realtime sessions.\n',
      ),
    ),
    delay: v.pipe(
      v.picklist(['minimal', 'low', 'medium', 'high', 'xhigh']),
      v.description(
        'Controls how long the model waits before emitting transcription text.\nHigher values can improve transcription accuracy at the cost of latency.\nOnly supported with `gpt-realtime-whisper` in GA Realtime sessions.\n',
      ),
    ),
  }),
)

export type AudioTranscription = v.InferOutput<typeof AudioTranscriptionSchema>

