export const GraderPythonSchema = v.pipe(
  v.object({
    type: v.pipe(v.literal('python'), v.description('The object type, which is always `python`.')),
    name: v.pipe(v.string(), v.description('The name of the grader.')),
    source: v.pipe(v.string(), v.description('The source code of the python script.')),
    image_tag: v.optional(
      v.pipe(v.string(), v.description('The image tag to use for the python script.')),
    ),
  }),
  v.description('A PythonGrader object that runs a python script on the input.\n'),
)

export type GraderPython = v.InferOutput<typeof GraderPythonSchema>

export const EvalGraderPythonSchema = v.intersect([
  GraderPythonSchema,
  v.partial(
    v.object({ pass_threshold: v.pipe(v.number(), v.description('The threshold for the score.')) }),
  ),
])

export type EvalGraderPython = v.InferOutput<typeof EvalGraderPythonSchema>

export const GraderScoreModelSchema = v.pipe(
  v.object({
    type: v.pipe(
      v.literal('score_model'),
      v.description('The object type, which is always `score_model`.'),
    ),
    name: v.pipe(v.string(), v.description('The name of the grader.')),
    model: v.pipe(v.string(), v.description('The model to use for the evaluation.')),
    sampling_params: v.optional(
      v.pipe(
        v.partial(
          v.object({
            seed: v.union([
              v.pipe(
                v.pipe(v.number(), v.integer()),
                v.description('A seed value to initialize the randomness, during sampling.\n'),
              ),
              v.nullable(v.null()),
            ]),
            top_p: v.union([
              v.pipe(
                v.optional(v.number(), 1),
                v.description(
                  'An alternative to temperature for nucleus sampling; 1.0 includes all tokens.\n',
                ),
                v.metadata({ examples: [1] }),
              ),
              v.nullable(v.null()),
            ]),
            temperature: v.union([
              v.pipe(
                v.number(),
                v.description('A higher temperature increases randomness in the outputs.\n'),
              ),
              v.nullable(v.null()),
            ]),
            max_completions_tokens: v.union([
              v.pipe(
                v.pipe(v.number(), v.integer(), v.minValue(1)),
                v.description(
                  'The maximum number of tokens the grader model may generate in its response.\n',
                ),
              ),
              v.nullable(v.null()),
            ]),
            reasoning_effort: ReasoningEffortSchema,
          }),
        ),
        v.description('The sampling parameters for the model.'),
      ),
    ),
    input: v.pipe(
      v.array(EvalItemSchema),
      v.description(
        'The input messages evaluated by the grader. Supports text, output text, input image, and input audio content blocks, and may include template strings.\n',
      ),
    ),
    range: v.optional(
      v.pipe(
        v.array(v.number()),
        v.description(
          'The service requires two numbers for the score range. Defaults to `[0, 1]`.\n',
        ),
      ),
    ),
  }),
  v.description('A ScoreModelGrader object that uses a model to assign a score to the input.\n'),
)

export type GraderScoreModel = v.InferOutput<typeof GraderScoreModelSchema>

export const EvalGraderScoreModelSchema = v.intersect([
  GraderScoreModelSchema,
  v.partial(
    v.object({ pass_threshold: v.pipe(v.number(), v.description('The threshold for the score.')) }),
  ),
])

export type EvalGraderScoreModel = v.InferOutput<typeof EvalGraderScoreModelSchema>

export const CreateEvalRequestSchema = v.object({
  name: v.optional(v.pipe(v.string(), v.description('The name of the evaluation.'))),
  metadata: v.optional(MetadataSchema),
  data_source_config: v.pipe(
    v.union([
      CreateEvalCustomDataSourceConfigSchema,
      CreateEvalLogsDataSourceConfigSchema,
      CreateEvalStoredCompletionsDataSourceConfigSchema,
    ]),
    v.description(
      'The configuration for the data source used for the evaluation runs. Dictates the schema of the data used in the evaluation.',
    ),
  ),
  testing_criteria: v.pipe(
    v.array(
      v.union([
        CreateEvalLabelModelGraderSchema,
        EvalGraderStringCheckSchema,
        EvalGraderTextSimilaritySchema,
        EvalGraderPythonSchema,
        EvalGraderScoreModelSchema,
      ]),
    ),
    v.description(
      "A list of graders for all eval runs in this group. Graders can reference variables in the data source using double curly braces notation, like `{{item.variable_name}}`. To reference the model's output, use the `sample` namespace (ie, `{{sample.output_text}}`).",
    ),
  ),
})

export type CreateEvalRequest = v.InferOutput<typeof CreateEvalRequestSchema>

export const TextResponseFormatConfigurationSchema = v.pipe(
  v.union([
    ResponseFormatTextSchema,
    TextResponseFormatJsonSchemaSchema,
    ResponseFormatJsonObjectSchema,
  ]),
  v.description(
    'An object specifying the format that the model must output.\n\nConfiguring `{ "type": "json_schema" }` enables Structured Outputs,\nwhich ensures the model will match your supplied JSON schema. Learn more in the\n[Structured Outputs guide](https://developers.openai.com/api/docs/guides/structured-outputs).\n\nThe default format is `{ "type": "text" }` with no additional options.\n\n**Not recommended for gpt-4o and newer models:**\n\nSetting to `{ "type": "json_object" }` enables the older JSON mode, which\nensures the message the model generates is valid JSON. Using `json_schema`\nis preferred for models that support it.\n',
  ),
)

export type TextResponseFormatConfiguration = v.InferOutput<
  typeof TextResponseFormatConfigurationSchema
>

export const EvalResponsesSourceSchema = v.pipe(
  v.object({
    type: v.pipe(
      v.literal('responses'),
      v.description('The type of run data source. Always `responses`.'),
    ),
    metadata: v.optional(
      v.union([
        v.pipe(
          v.object({}),
          v.description(
            'Metadata filter for the responses. This is a query parameter used to select responses.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    model: v.optional(
      v.union([
        v.pipe(
          v.string(),
          v.description(
            'The name of the model to find responses for. This is a query parameter used to select responses.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    instructions_search: v.optional(
      v.union([
        v.pipe(
          v.string(),
          v.description(
            "Optional string to search the 'instructions' field. This is a query parameter used to select responses.",
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    created_after: v.optional(
      v.union([
        v.pipe(
          v.pipe(v.number(), v.integer(), v.minValue(0)),
          v.description(
            'Only include items created after this timestamp (inclusive). This is a query parameter used to select responses.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    created_before: v.optional(
      v.union([
        v.pipe(
          v.pipe(v.number(), v.integer(), v.minValue(0)),
          v.description(
            'Only include items created before this timestamp (inclusive). This is a query parameter used to select responses.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    reasoning_effort: v.optional(
      v.union([
        v.pipe(
          ReasoningEffortSchema,
          v.description(
            'Optional reasoning effort parameter. This is a query parameter used to select responses.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    temperature: v.optional(
      v.union([
        v.pipe(
          v.number(),
          v.description(
            'Sampling temperature. This is a query parameter used to select responses.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    top_p: v.optional(
      v.union([
        v.pipe(
          v.number(),
          v.description(
            'Nucleus sampling parameter. This is a query parameter used to select responses.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    users: v.optional(
      v.union([
        v.pipe(
          v.array(v.string()),
          v.description(
            'List of user identifiers. This is a query parameter used to select responses.',
          ),
        ),
        v.nullable(v.null()),
      ]),
    ),
    tools: v.optional(
      v.union([
        v.pipe(
          v.array(v.string()),
          v.description('List of tool names. This is a query parameter used to select responses.'),
        ),
        v.nullable(v.null()),
      ]),
    ),
  }),
  v.description('A EvalResponsesSource object describing a run data source configuration.\n'),
)

export type EvalResponsesSource = v.InferOutput<typeof EvalResponsesSourceSchema>

export const CreateEvalResponsesRunDataSourceSchema = v.pipe(
  v.object({
    type: v.pipe(
      v.optional(v.literal('responses'), 'responses'),
      v.description('The type of run data source. Always `responses`.'),
    ),
    input_messages: v.optional(
      v.pipe(
        v.union([
          v.object({
            type: v.pipe(
              v.literal('template'),
              v.description('The type of input messages. Always `template`.'),
            ),
            template: v.pipe(
              v.array(
                v.union([
                  v.object({
                    role: v.pipe(
                      v.string(),
                      v.description(
                        'The role of the message (e.g. "system", "assistant", "user").',
                      ),
                    ),
                    content: v.pipe(v.string(), v.description('The content of the message.')),
                  }),
                  EvalItemSchema,
                ]),
              ),
              v.description(
                'A list of chat messages forming the prompt or context. May include variable references to the `item` namespace, ie {{item.name}}.',
              ),
            ),
          }),
          v.object({
            type: v.pipe(
              v.literal('item_reference'),
              v.description('The type of input messages. Always `item_reference`.'),
            ),
            item_reference: v.pipe(
              v.string(),
              v.description('A reference to a variable in the `item` namespace. Ie, "item.name"'),
            ),
          }),
        ]),
        v.description(
          'Used when sampling from a model. Dictates the structure of the messages passed into the model. Can either be a reference to a prebuilt trajectory (ie, `item.input_trajectory`), or a template with variable references to the `item` namespace.',
        ),
      ),
    ),
    sampling_params: v.optional(
      v.object({
        reasoning_effort: v.optional(ReasoningEffortSchema),
        temperature: v.pipe(
          v.optional(v.number(), 1),
          v.description('A higher temperature increases randomness in the outputs.'),
        ),
        max_completion_tokens: v.optional(
          v.pipe(
            v.pipe(v.number(), v.integer()),
            v.description('The maximum number of tokens in the generated output.'),
          ),
        ),
        top_p: v.pipe(
          v.optional(v.number(), 1),
          v.description(
            'An alternative to temperature for nucleus sampling; 1.0 includes all tokens.',
          ),
        ),
        seed: v.pipe(
          v.optional(v.pipe(v.number(), v.integer()), 42),
          v.description('A seed value to initialize the randomness, during sampling.'),
        ),
        tools: v.optional(
          v.pipe(
            v.array(ToolSchema),
            v.description(
              "An array of tools the model may call while generating a response. You\ncan specify which tool to use by setting the `tool_choice` parameter.\n\nThe two categories of tools you can provide the model are:\n\n- **Built-in tools**: Tools that are provided by OpenAI that extend the\n  model's capabilities, like [web search](https://developers.openai.com/api/docs/guides/tools-web-search)\n  or [file search](https://developers.openai.com/api/docs/guides/tools-file-search). Learn more about\n  [built-in tools](https://developers.openai.com/api/docs/guides/tools).\n- **Function calls (custom tools)**: Functions that are defined by you,\n  enabling the model to call your own code. Learn more about\n  [function calling](https://developers.openai.com/api/docs/guides/function-calling).\n",
            ),
          ),
        ),
        text: v.optional(
          v.pipe(
            v.partial(v.object({ format: TextResponseFormatConfigurationSchema })),
            v.description(
              'Configuration options for a text response from the model. Can be plain\ntext or structured JSON data. Learn more:\n- [Text inputs and outputs](https://developers.openai.com/api/docs/guides/text)\n- [Structured Outputs](https://developers.openai.com/api/docs/guides/structured-outputs)\n',
            ),
          ),
        ),
      }),
    ),
    model: v.optional(
      v.pipe(
        v.string(),
        v.description('The model to use to sample outputs with the Responses API.'),
      ),
    ),
    source: v.pipe(
      v.union([
        EvalJsonlFileContentSourceSchema,
        EvalJsonlFileIdSourceSchema,
        EvalResponsesSourceSchema,
      ]),
      v.description("Determines what populates the `item` namespace in this run's data source."),
    ),
  }),
  v.description('A ResponsesRunDataSource object describing a model sampling configuration.\n'),
)

export type CreateEvalResponsesRunDataSource = v.InferOutput<
  typeof CreateEvalResponsesRunDataSourceSchema
>

export const CreateEvalRunRequestSchema = v.object({
  name: v.optional(v.pipe(v.string(), v.description('The name of the run.'))),
  metadata: v.optional(MetadataSchema),
  data_source: v.pipe(
    v.union([
      CreateEvalJsonlRunDataSourceSchema,
      CreateEvalCompletionsRunDataSourceSchema,
      CreateEvalResponsesRunDataSourceSchema,
    ]),
    v.description("Details about the run's data source."),
  ),
})

export type CreateEvalRunRequest = v.InferOutput<typeof CreateEvalRunRequestSchema>

export const FileExpirationAfterSchema = v.pipe(
  v.object({
    anchor: v.pipe(
      v.literal('created_at'),
      v.description(
        'Anchor timestamp after which the expiration policy applies. Supported anchors: `created_at`.',
      ),
    ),
    seconds: v.pipe(
      v.pipe(
        v.union([
          v.bigint(),
          v.pipe(v.number(), v.integer()),
          v.pipe(v.string(), v.regex(/^-?\d+$/)),
        ]),
        v.transform((input) => BigInt(input)),
        v.minValue(-9223372036854775808n),
        v.maxValue(9223372036854775807n),
        v.minValue(3600n),
        v.maxValue(2592000n),
      ),
      v.description(
        'The number of seconds after the anchor time that the file will expire. Must be between 3600 (1 hour) and 2592000 (30 days).',
      ),
    ),
  }),
  v.description(
    'The expiration policy for a file. By default, files with `purpose=batch` expire after 30 days and all other files are persisted until they are manually deleted.',
  ),
)

export type FileExpirationAfter = v.InferOutput<typeof FileExpirationAfterSchema>

export const CreateFileRequestSchema = v.strictObject({
  file: v.pipe(v.file(), v.description('The File object (not file name) to be uploaded.\n')),
  purpose: v.pipe(
    v.picklist(['assistants', 'batch', 'fine-tune', 'vision', 'user_data', 'evals']),
    v.description(
      'The intended purpose of the uploaded file. One of:\n- `assistants`: Used in the Assistants API\n- `batch`: Used in the Batch API\n- `fine-tune`: Used for fine-tuning\n- `vision`: Images used for vision fine-tuning\n- `user_data`: Flexible file type for any purpose\n- `evals`: Used for eval data sets\n',
    ),
  ),
  expires_after: v.optional(FileExpirationAfterSchema),
})

export type CreateFileRequest = v.InferOutput<typeof CreateFileRequestSchema>

