export const TranscriptionSegmentSchema = v.object({
  id: v.pipe(v.pipe(v.number(), v.integer()), v.description('Unique identifier of the segment.')),
  seek: v.pipe(v.pipe(v.number(), v.integer()), v.description('Seek offset of the segment.')),
  start: v.pipe(v.number(), v.description('Start time of the segment in seconds.')),
  end: v.pipe(v.number(), v.description('End time of the segment in seconds.')),
  text: v.pipe(v.string(), v.description('Text content of the segment.')),
  tokens: v.pipe(
    v.array(v.pipe(v.number(), v.integer())),
    v.description('Array of token IDs for the text content.'),
  ),
  temperature: v.pipe(
    v.pipe(v.number(), v.minValue(-3.4028234663852886e38), v.maxValue(3.4028234663852886e38)),
    v.description('Temperature parameter used for generating the segment.'),
  ),
  avg_logprob: v.pipe(
    v.pipe(v.number(), v.minValue(-3.4028234663852886e38), v.maxValue(3.4028234663852886e38)),
    v.description(
      'Average logprob of the segment. If the value is lower than -1, consider the logprobs failed.',
    ),
  ),
  compression_ratio: v.pipe(
    v.pipe(v.number(), v.minValue(-3.4028234663852886e38), v.maxValue(3.4028234663852886e38)),
    v.description(
      'Compression ratio of the segment. If the value is greater than 2.4, consider the compression failed.',
    ),
  ),
  no_speech_prob: v.pipe(
    v.pipe(v.number(), v.minValue(-3.4028234663852886e38), v.maxValue(3.4028234663852886e38)),
    v.description(
      'Probability of no speech in the segment. If the value is higher than 1.0 and the `avg_logprob` is below -1, consider this segment silent.',
    ),
  ),
})

