export const EditImageBodyJsonParamSchema = v.pipe(
  v.object({
    frame_count: v.optional(FrameCountSchema),
    frame_duration_ms: v.optional(FrameDurationMsSchema),
    complexity: v.optional(ComplexitySchema),
    model: v.pipe(
      v.optional(
        v.union([
          v.string(),
          v.picklist([
            'gpt-image-1.5',
            'gpt-image-2',
            'gpt-image-2-2026-04-21',
            'gpt-image-2.5-sunburst',
            'gpt-image-2.5-sunburst-2026-09-08',
            'gpt-image-2.5-flare',
            'gpt-image-2.5-flare-2026-09-08',
            'gpt-image-2.6-sunburst',
            'gpt-image-2.6-flare',
            'gpt-image-1',
            'gpt-image-1-mini',
            'chatgpt-image-latest',
          ]),
          v.nullable(v.null()),
        ]),
        'gpt-image-2.6-sunburst',
      ),
      v.description(
        'The GPT image model to use for image editing, including `gpt-image-2`, its dated\nsnapshot `gpt-image-2-2026-04-21`, `gpt-image-2.5-sunburst`,\n`gpt-image-2.5-sunburst-2026-09-08`, `gpt-image-2.5-flare`,\n`gpt-image-2.5-flare-2026-09-08`, `gpt-image-2.6-sunburst`, and `gpt-image-2.6-flare`.\nDefaults to `gpt-image-2.6-sunburst`.\n\n`gpt-image-1` was shut down on October 23, 2026. Use\n`gpt-image-2.5-sunburst` or `gpt-image-2.5-flare` instead.\n',
      ),
    ),
    images: v.pipe(
      v.pipe(v.array(ImageRefParamSchema), v.minLength(1), v.maxLength(16)),
      v.description(
        'Input image references to edit.\nFor GPT image models, you can provide up to 16 images.\n',
      ),
    ),
    mask: v.optional(ImageRefParamSchema),
    markup: v.optional(
      v.pipe(
        ImageRefParamSchema,
        v.description(
          "A transparent PNG overlaid on the first image, referenced by file ID, HTTPS URL, or base64 data URL. Must match that image's dimensions after orientation and contain transparent pixels. Supports GPT Image 2.5. Cannot be combined with mask.",
        ),
      ),
    ),
    prompt: v.pipe(
      v.pipe(v.string(), v.minCodePoints(1), v.maxCodePoints(32000)),
      v.description('A text description of the desired image edit.'),
      v.metadata({ examples: ['Add a watercolor effect and keep the subject centered'] }),
    ),
    n: v.pipe(
      v.optional(
        v.union([
          v.pipe(v.number(), v.integer(), v.minValue(1), v.maxValue(10)),
          v.nullable(v.null()),
        ]),
        1,
      ),
      v.description('The number of edited images to generate.'),
      v.metadata({ examples: [1] }),
    ),
    quality: v.pipe(
      v.optional(
        v.union([
          v.picklist(['low', 'medium', 'high', 'xhigh', 'max', 'auto']),
          v.nullable(v.null()),
        ]),
        'auto',
      ),
      v.description(
        'Output quality for GPT image models. The GPT image models support `low`, `medium`,\nand `high`. `gpt-image-2.5-sunburst` and `gpt-image-2.5-flare`, including their\n`2026-09-08` snapshots, also support `xhigh` and `max`. Defaults to `auto`.\n',
      ),
      v.metadata({ examples: ['high'] }),
    ),
    input_fidelity: v.optional(
      v.pipe(
        v.union([v.picklist(['high', 'low']), v.nullable(v.null())]),
        v.description(
          'Control how much effort the model will exert to match the style and features, especially facial features, of input images. Supports `high` and `low` on `gpt-image-1.5`; `gpt-image-1-mini` supports only `low`. For `gpt-image-2`, omit this parameter. Defaults to `low` on supported models.',
        ),
      ),
    ),
    size: v.pipe(
      v.optional(
        v.union([
          v.string(),
          v.picklist(['auto', '1024x1024', '1536x1024', '1024x1536']),
          v.nullable(v.null()),
        ]),
        'auto',
      ),
      v.description(
        "The size of the generated images. For `gpt-image-2`, `gpt-image-2-2026-04-21`, `gpt-image-2.5-sunburst`, `gpt-image-2.5-sunburst-2026-09-08`, `gpt-image-2.5-flare`, and `gpt-image-2.5-flare-2026-09-08`, arbitrary resolutions are supported as `WIDTHxHEIGHT` strings, for example `1536x864`. Width and height must both be divisible by 16 and the requested aspect ratio must be between 1:3 and 3:1. Resolutions above `2560x1440` are experimental, and the maximum supported resolution is `3840x2160`. The requested size must also satisfy the model's current pixel and edge limits. The standard sizes `1024x1024`, `1536x1024`, and `1024x1536` are supported by the GPT image models; `auto` is supported for models that allow automatic sizing.",
      ),
      v.metadata({ examples: ['1024x1024'] }),
    ),
    safety_identifier: v.optional(
      v.pipe(
        v.nullable(v.pipe(v.string(), v.maxCodePoints(128))),
        v.description(
          'A stable identifier for an end user in your organization, used for safety monitoring and abuse detection. Hash a username or email address to avoid sending identifying information. A non-empty value takes precedence over the deprecated `user` parameter. If omitted, null, or empty, the API uses `user` when available. [Learn more](https://developers.openai.com/api/docs/guides/safety-best-practices#implement-safety-identifiers).',
        ),
        v.metadata({ examples: ['user-1234'] }),
      ),
    ),
    user: v.optional(
      v.pipe(
        v.string(),
        v.description(
          'Deprecated: use `safety_identifier` instead. This parameter remains accepted for backward compatibility and is used when `safety_identifier` is omitted, null, or empty. [Learn more](https://developers.openai.com/api/docs/guides/safety-best-practices#implement-safety-identifiers).',
        ),
        v.metadata({ examples: ['user-1234'], deprecated: true }),
      ),
    ),
    output_format: v.pipe(
      v.optional(v.union([ImagesApiOutputFormatSchema, v.nullable(v.null())]), 'png'),
      v.description(
        'Output image format. Supported for GPT image models. SVG output requires a supported image model and project access.',
      ),
      v.metadata({ examples: ['png'] }),
    ),
    svg: v.optional(
      v.pipe(
        v.union([SvgParamSchema, v.nullable(v.null())]),
        v.description(
          'Selects the author model and reasoning effort for `output_format=svg`. Supply `svg.model` when SVG model selection is enabled. Otherwise, omit this object. SVG output requires `n=1` and cannot use streaming, partial images, or output compression.',
        ),
      ),
    ),
    output_compression: v.optional(
      v.pipe(
        v.union([
          v.pipe(v.number(), v.integer(), v.minValue(0), v.maxValue(100)),
          v.nullable(v.null()),
        ]),
        v.description('Compression level for `jpeg` or `webp` output.'),
        v.metadata({ examples: [100] }),
      ),
    ),
    moderation: v.pipe(
      v.optional(v.union([v.picklist(['low', 'auto']), v.nullable(v.null())]), 'auto'),
      v.description('Moderation level for GPT image models.'),
      v.metadata({ examples: ['auto'] }),
    ),
    background: v.pipe(
      v.optional(
        v.union([v.picklist(['transparent', 'opaque', 'auto']), v.nullable(v.null())]),
        'auto',
      ),
      v.description(
        'Set the background of the generated image output. `gpt-image-2.5-sunburst` and `gpt-image-2.5-flare`, including their `2026-09-08` snapshots, support `opaque` and `transparent` backgrounds. Transparent backgrounds are available for supported GPT Image models. For `gpt-image-2` and `gpt-image-2-2026-04-21`, this support is in preview. When using `transparent`, set the output format to `png` or `webp`.',
      ),
      v.metadata({ examples: ['transparent'] }),
    ),
    stream: v.pipe(
      v.optional(v.union([v.boolean(), v.nullable(v.null())]), false),
      v.description('Stream partial image results as events.'),
      v.metadata({ examples: [false] }),
    ),
    partial_images: v.optional(PartialImagesSchema),
  }),
  v.description(
    'JSON request body for image edits.\n\nUse `images` (array of `ImageRefParam`) instead of multipart `image` uploads.\nYou can reference images via external URLs, data URLs, or uploaded file IDs.\nJSON edits support GPT image models.\n',
  ),
)

