export const EvalSchema = v.pipe(
  v.object({
    object: v.pipe(v.optional(v.literal('eval'), 'eval'), v.description('The object type.')),
    id: v.pipe(v.string(), v.description('Unique identifier for the evaluation.')),
    name: v.pipe(
      v.string(),
      v.description('The name of the evaluation.'),
      v.metadata({ examples: ['Chatbot effectiveness Evaluation'] }),
    ),
    data_source_config: v.pipe(
      v.union([
        EvalCustomDataSourceConfigSchema,
        EvalLogsDataSourceConfigSchema,
        EvalStoredCompletionsDataSourceConfigSchema,
      ]),
      v.description('Configuration of data sources used in runs of the evaluation.'),
    ),
    testing_criteria: v.pipe(
      v.array(
        v.union([
          EvalGraderLabelModelSchema,
          EvalGraderStringCheckSchema,
          EvalGraderTextSimilaritySchema,
          EvalGraderPythonSchema,
          EvalGraderScoreModelSchema,
        ]),
      ),
      v.description('A list of testing criteria.'),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The Unix timestamp (in seconds) for when the eval was created.'),
    ),
    metadata: MetadataSchema,
  }),
  v.description(
    'An Eval object with a data source config and testing criteria.\nAn Eval represents a task to be done for your LLM integration.\nLike:\n - Improve the quality of my chatbot\n - See how well my chatbot handles customer support\n - Compare how different models perform on the same task\n',
  ),
)

export type Eval = v.InferOutput<typeof EvalSchema>

