export const EvalRunSchema = v.pipe(
  v.object({
    object: v.pipe(
      v.optional(v.literal('eval.run'), 'eval.run'),
      v.description('The type of the object. Always "eval.run".'),
    ),
    id: v.pipe(v.string(), v.description('Unique identifier for the evaluation run.')),
    eval_id: v.pipe(v.string(), v.description('The identifier of the associated evaluation.')),
    status: v.pipe(v.string(), v.description('The status of the evaluation run.')),
    model: v.pipe(
      v.nullable(v.string()),
      v.description('The model that is evaluated, if applicable.'),
    ),
    name: v.pipe(v.nullable(v.string()), v.description('The name of the evaluation run.')),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('Unix timestamp (in seconds) when the evaluation run was created.'),
    ),
    report_url: v.pipe(
      v.pipe(v.string(), v.url()),
      v.description('The URL to the rendered evaluation run report on the UI dashboard.'),
    ),
    result_counts: v.pipe(
      v.object({
        total: v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description('Total number of executed output items.'),
        ),
        errored: v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description('Number of output items that resulted in an error.'),
        ),
        failed: v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description('Number of output items that failed to pass the evaluation.'),
        ),
        passed: v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description('Number of output items that passed the evaluation.'),
        ),
      }),
      v.description('Counters summarizing the outcomes of the evaluation run.'),
    ),
    per_model_usage: v.pipe(
      v.nullable(
        v.array(
          v.object({
            model_name: v.pipe(v.string(), v.description('The name of the model.')),
            invocation_count: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The number of invocations.'),
            ),
            prompt_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The number of prompt tokens used.'),
            ),
            completion_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The number of completion tokens generated.'),
            ),
            total_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The total number of tokens used.'),
            ),
            cached_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The number of tokens retrieved from cache.'),
            ),
          }),
        ),
      ),
      v.description('Usage statistics for each model during the evaluation run.'),
    ),
    per_testing_criteria_results: v.pipe(
      v.nullable(
        v.array(
          v.object({
            testing_criteria: v.pipe(
              v.string(),
              v.description('A description of the testing criteria.'),
            ),
            passed: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('Number of tests passed for this criteria.'),
            ),
            failed: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('Number of tests failed for this criteria.'),
            ),
          }),
        ),
      ),
      v.description('Results per testing criteria applied during the evaluation run.'),
    ),
    data_source: v.pipe(
      v.union([
        CreateEvalJsonlRunDataSourceSchema,
        CreateEvalCompletionsRunDataSourceSchema,
        CreateEvalResponsesRunDataSourceSchema,
      ]),
      v.description("Information about the run's data source."),
    ),
    metadata: MetadataSchema,
    error: v.union([EvalApiErrorSchema, v.nullable(v.null())]),
  }),
  v.description('A schema representing an evaluation run.\n'),
)

export type EvalRun = v.InferOutput<typeof EvalRunSchema>

