export const EvalRunOutputItemSchema = v.pipe(
  v.object({
    object: v.pipe(
      v.optional(v.literal('eval.run.output_item'), 'eval.run.output_item'),
      v.description('The type of the object. Always "eval.run.output_item".'),
    ),
    id: v.pipe(v.string(), v.description('Unique identifier for the evaluation run output item.')),
    run_id: v.pipe(
      v.string(),
      v.description('The identifier of the evaluation run associated with this output item.'),
    ),
    eval_id: v.pipe(v.string(), v.description('The identifier of the evaluation group.')),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('Unix timestamp (in seconds) when the evaluation run was created.'),
    ),
    status: v.pipe(v.string(), v.description('The status of the evaluation run.')),
    datasource_item_id: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The identifier for the data source item.'),
    ),
    datasource_item: v.pipe(v.any(), v.description('Details of the input data source item.')),
    results: v.pipe(
      v.array(EvalRunOutputItemResultSchema),
      v.description('A list of grader results for this output item.'),
    ),
    sample: v.pipe(
      v.object({
        input: v.pipe(
          v.array(
            v.pipe(
              v.object({
                role: v.pipe(
                  v.string(),
                  v.description('The role of the message sender (e.g., system, user, developer).'),
                ),
                content: v.pipe(v.string(), v.description('The content of the message.')),
              }),
              v.description('An input message.'),
            ),
          ),
          v.description('An array of input messages.'),
        ),
        output: v.pipe(
          v.array(
            v.partial(
              v.object({
                role: v.pipe(
                  v.string(),
                  v.description('The role of the message (e.g. "system", "assistant", "user").'),
                ),
                content: v.pipe(v.string(), v.description('The content of the message.')),
              }),
            ),
          ),
          v.description('An array of output messages.'),
        ),
        finish_reason: v.pipe(
          v.string(),
          v.description('The reason why the sample generation was finished.'),
        ),
        model: v.pipe(v.string(), v.description('The model used for generating the sample.')),
        usage: v.pipe(
          v.object({
            total_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The total number of tokens used.'),
            ),
            completion_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The number of completion tokens generated.'),
            ),
            prompt_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The number of prompt tokens used.'),
            ),
            cached_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description('The number of tokens retrieved from cache.'),
            ),
          }),
          v.description('Token usage details for the sample.'),
        ),
        error: v.union([EvalApiErrorSchema, v.nullable(v.null())]),
        temperature: v.pipe(v.number(), v.description('The sampling temperature used.')),
        max_completion_tokens: v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description('The maximum number of tokens allowed for completion.'),
        ),
        top_p: v.pipe(v.number(), v.description('The top_p value used for sampling.')),
        seed: v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description('The seed used for generating the sample.'),
        ),
      }),
      v.description('A sample containing the input and output of the evaluation run.'),
    ),
  }),
  v.description('A schema representing an evaluation run output item.\n'),
)

export type EvalRunOutputItem = v.InferOutput<typeof EvalRunOutputItemSchema>

