export const FineTuningIntegrationSchema = v.object({
  type: v.pipe(
    v.literal('wandb'),
    v.description('The type of the integration being enabled for the fine-tuning job'),
  ),
  wandb: v.pipe(
    v.object({
      project: v.pipe(
        v.string(),
        v.description('The name of the project that the new run will be created under.\n'),
        v.metadata({ examples: ['my-wandb-project'] }),
      ),
      name: v.optional(
        v.union([
          v.pipe(
            v.string(),
            v.description(
              'A display name to set for the run. If not set, we will use the Job ID as the name.\n',
            ),
          ),
          v.nullable(v.null()),
        ]),
      ),
      entity: v.optional(
        v.union([
          v.pipe(
            v.string(),
            v.description(
              'The entity to use for the run. This allows you to set the team or username of the WandB user that you would\nlike associated with the run. If not set, the default entity for the registered WandB API key is used.\n',
            ),
          ),
          v.nullable(v.null()),
        ]),
      ),
      tags: v.optional(
        v.pipe(
          v.array(v.pipe(v.string(), v.metadata({ examples: ['custom-tag'] }))),
          v.description(
            'A list of tags to be attached to the newly created run. These tags are passed through directly to WandB. Some\ndefault tags are generated by OpenAI: "openai/finetune", "openai/{base-model}", "openai/{ftjob-abcdef}".\n',
          ),
        ),
      ),
    }),
    v.description(
      'The settings for your integration with Weights and Biases. This payload specifies the project that\nmetrics will be sent to. Optionally, you can set an explicit display name for your run, add tags\nto your run, and set a default entity (team, username, etc) to be associated with your run.\n',
    ),
  ),
})

export type FineTuningIntegration = v.InferOutput<typeof FineTuningIntegrationSchema>

export const FineTuningJobSchema = v.pipe(
  v.pipe(
    v.looseObject({
      id: v.pipe(
        v.string(),
        v.description('The object identifier, which can be referenced in the API endpoints.'),
      ),
      created_at: v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('The Unix timestamp (in seconds) for when the fine-tuning job was created.'),
      ),
      error: v.union([
        v.pipe(
          v.object({
            code: v.pipe(v.string(), v.description('A machine-readable error code.')),
            message: v.pipe(v.string(), v.description('A human-readable error message.')),
            param: v.union([
              v.pipe(
                v.string(),
                v.description(
                  'The parameter that was invalid, usually `training_file` or `validation_file`. This field will be null if the failure was not parameter-specific.',
                ),
              ),
              v.nullable(v.null()),
            ]),
          }),
          v.description(
            'For fine-tuning jobs that have `failed`, this will contain more information on the cause of the failure.',
          ),
        ),
        v.nullable(v.null()),
        v.object({}),
      ]),
      fine_tuned_model: v.union([
        v.pipe(
          v.string(),
          v.description(
            'The name of the fine-tuned model that is being created. The value will be null if the fine-tuning job is still running.',
          ),
        ),
        v.nullable(v.null()),
      ]),
      finished_at: v.union([
        v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description(
            'The Unix timestamp (in seconds) for when the fine-tuning job was finished. The value will be null if the fine-tuning job is still running.',
          ),
        ),
        v.nullable(v.null()),
      ]),
      hyperparameters: v.optional(
        v.pipe(
          v.nullable(
            v.object({
              batch_size: v.optional(
                v.union([
                  v.pipe(
                    v.optional(
                      v.union([
                        v.literal('auto'),
                        v.pipe(v.number(), v.integer(), v.minValue(1), v.maxValue(256)),
                      ]),
                      'auto',
                    ),
                    v.description(
                      'Number of examples in each batch. A larger batch size means that model parameters\nare updated less frequently, but with lower variance.\n',
                    ),
                  ),
                  v.nullable(v.null()),
                ]),
              ),
              learning_rate_multiplier: v.pipe(
                v.optional(v.union([v.literal('auto'), v.pipe(v.number(), v.gtValue(0))]), 'auto'),
                v.description(
                  'Scaling factor for the learning rate. A smaller learning rate may be useful to avoid\noverfitting.\n',
                ),
              ),
              n_epochs: v.pipe(
                v.optional(
                  v.union([
                    v.literal('auto'),
                    v.pipe(v.number(), v.integer(), v.minValue(1), v.maxValue(50)),
                  ]),
                  'auto',
                ),
                v.description(
                  'The number of epochs to train the model for. An epoch refers to one full cycle\nthrough the training dataset.\n',
                ),
              ),
            }),
          ),
          v.description(
            'The hyperparameters used for the fine-tuning job. This value will only be returned when running `supervised` jobs.',
          ),
        ),
      ),
      model: v.pipe(v.string(), v.description('The base model that is being fine-tuned.')),
      object: v.pipe(
        v.literal('fine_tuning.job'),
        v.description('The object type, which is always "fine_tuning.job".'),
      ),
      organization_id: v.pipe(
        v.string(),
        v.description('The organization that owns the fine-tuning job.'),
      ),
      result_files: v.pipe(
        v.array(v.pipe(v.string(), v.metadata({ examples: ['file-abc123'] }))),
        v.description(
          'The compiled results file ID(s) for the fine-tuning job. You can retrieve the results with the [Files API](https://developers.openai.com/api/reference/resources/files/methods/content).',
        ),
      ),
      status: v.pipe(
        v.picklist([
          'validating_files',
          'queued',
          'running',
          'succeeded',
          'failed',
          'cancelled',
          'pausing',
          'paused',
        ]),
        v.description(
          'The current status of the fine-tuning job, which can be `validating_files`, `queued`, `running`, `pausing`, `paused`, `succeeded`, `failed`, or `cancelled`.',
        ),
      ),
      trained_tokens: v.union([
        v.pipe(
          v.pipe(v.number(), v.integer()),
          v.description(
            'The total number of billable tokens processed by this fine-tuning job. The value will be null if the fine-tuning job is still running.',
          ),
        ),
        v.nullable(v.null()),
      ]),
      training_file: v.pipe(
        v.string(),
        v.description(
          'The file ID used for training. You can retrieve the training data with the [Files API](https://developers.openai.com/api/reference/resources/files/methods/content).',
        ),
      ),
      validation_file: v.union([
        v.pipe(
          v.string(),
          v.description(
            'The file ID used for validation. You can retrieve the validation results with the [Files API](https://developers.openai.com/api/reference/resources/files/methods/content).',
          ),
        ),
        v.nullable(v.null()),
      ]),
      integrations: v.optional(
        v.union([
          v.pipe(
            v.pipe(v.array(v.union([FineTuningIntegrationSchema])), v.maxLength(5)),
            v.description('A list of integrations to enable for this fine-tuning job.'),
          ),
          v.nullable(v.null()),
        ]),
      ),
      seed: v.pipe(
        v.nullable(v.pipe(v.number(), v.integer())),
        v.description('The seed used for the fine-tuning job.'),
      ),
      estimated_finish: v.optional(
        v.union([
          v.pipe(
            v.pipe(v.number(), v.integer()),
            v.description(
              'The Unix timestamp (in seconds) for when the fine-tuning job is estimated to finish. The value will be null if the fine-tuning job is not running.',
            ),
          ),
          v.nullable(v.null()),
        ]),
      ),
      method: v.optional(v.union([FineTuneMethodSchema, v.nullable(v.null())])),
      metadata: v.optional(MetadataSchema),
    }),
    v.check(
      (input) =>
        v.safeParse(
          v.object({ method: v.object({ type: v.picklist(['dpo', 'reinforcement']) }) }),
          input,
        ).success || v.safeParse(v.any(), input).success,
    ),
  ),
  v.description(
    'The `fine_tuning.job` object represents a fine-tuning job that has been created through the API.\n',
  ),
)

export type FineTuningJob = v.InferOutput<typeof FineTuningJobSchema>

