export const OpenAIFileSchema = v.pipe(
  v.object({
    id: v.pipe(
      v.string(),
      v.description('The file identifier, which can be referenced in the API endpoints.'),
    ),
    bytes: v.pipe(
      v.nullable(v.pipe(v.number(), v.integer())),
      v.description(
        'The size of the file, in bytes. In a completed file upload response, this can\nbe null when the file size is not yet available.\n',
      ),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('The Unix timestamp (in seconds) for when the file was created.'),
    ),
    expires_at: v.optional(
      v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description(
          'The Unix timestamp (in seconds) for when the file will expire. In a\ncompleted file upload response, this can be null when no expiry is set.\n',
        ),
      ),
    ),
    filename: v.pipe(v.string(), v.description('The name of the file.')),
    object: v.pipe(v.literal('file'), v.description('The object type, which is always `file`.')),
    purpose: v.pipe(
      v.picklist([
        'assistants',
        'assistants_output',
        'batch',
        'batch_output',
        'fine-tune',
        'fine-tune-results',
        'vision',
        'user_data',
      ]),
      v.description(
        'The intended purpose of the file. Supported values are `assistants`, `assistants_output`, `batch`, `batch_output`, `fine-tune`, `fine-tune-results`, `vision`, and `user_data`.',
      ),
    ),
    status: v.pipe(
      v.picklist(['uploaded', 'processed', 'error']),
      v.description(
        'Deprecated. The current status of the file, which can be either `uploaded`, `processed`, or `error`.',
      ),
      v.metadata({ deprecated: true }),
    ),
    status_details: v.optional(
      v.pipe(
        v.string(),
        v.description(
          'Deprecated. For details on why a fine-tuning training file failed validation, see the `error` field on `fine_tuning.job`. Completed file upload responses can return null when these details are unset.',
        ),
        v.metadata({ deprecated: true }),
      ),
    ),
  }),
  v.description('The `File` object represents a document that has been uploaded to OpenAI.'),
)

