export const RealtimeBetaResponseCreateParamsSchema = v.pipe(
  v.object({
    modalities: v.optional(
      v.pipe(
        v.array(v.picklist(['text', 'audio'])),
        v.description(
          'The set of modalities the model can respond with. To disable audio,\nset this to ["text"].\n',
        ),
      ),
    ),
    instructions: v.optional(
      v.pipe(
        v.string(),
        v.description(
          'The default system instructions (i.e. system message) prepended to model \ncalls. This field allows the client to guide the model on desired \nresponses. The model can be instructed on response content and format, \n(e.g. "be extremely succinct", "act friendly", "here are examples of good \nresponses") and on audio behavior (e.g. "talk quickly", "inject emotion \ninto your voice", "laugh frequently"). The instructions are not guaranteed \nto be followed by the model, but they provide guidance to the model on the \ndesired behavior.\n\nNote that the server sets default instructions which will be used if this \nfield is not set and are visible in the `session.created` event at the \nstart of the session.\n',
        ),
      ),
    ),
    voice: v.optional(
      v.pipe(
        VoiceIdsOrCustomVoiceSchema,
        v.description(
          'The voice the model uses to respond. Supported built-in voices are\n`alloy`, `ash`, `ballad`, `coral`, `echo`, `sage`, `shimmer`, `verse`,\n`marin`, and `cedar`. You may also provide a custom voice object with an\n`id`, for example `{ "id": "voice_1234" }`. Voice cannot be changed during\nthe session once the model has responded with audio at least once.\nCustom voices must be created from audio samples. Voices created from text prompts are supported only in Live.\n',
        ),
      ),
    ),
    output_audio_format: v.optional(
      v.pipe(
        v.picklist(['pcm16', 'g711_ulaw', 'g711_alaw']),
        v.description(
          'The format of output audio. Options are `pcm16`, `g711_ulaw`, or `g711_alaw`.\n',
        ),
      ),
    ),
    tools: v.optional(
      v.pipe(
        v.array(
          v.partial(
            v.object({
              type: v.pipe(
                v.literal('function'),
                v.description('The type of the tool, i.e. `function`.'),
              ),
              name: v.pipe(v.string(), v.description('The name of the function.')),
              description: v.pipe(
                v.string(),
                v.description(
                  'The description of the function, including guidance on when and how \nto call it, and guidance about what to tell the user when calling \n(if anything).\n',
                ),
              ),
              parameters: v.pipe(
                v.object({}),
                v.description('Parameters of the function in JSON Schema.'),
              ),
            }),
          ),
        ),
        v.description('Tools (functions) available to the model.'),
      ),
    ),
    tool_choice: v.pipe(
      v.optional(
        v.union([ToolChoiceOptionsSchema, ToolChoiceFunctionSchema, ToolChoiceMCPSchema]),
        'auto',
      ),
      v.description(
        'How the model chooses tools. Provide one of the string modes or force a specific\nfunction/MCP tool.\n',
      ),
    ),
    temperature: v.optional(
      v.pipe(
        v.number(),
        v.description(
          'Sampling temperature for the model, limited to [0.6, 1.2]. Defaults to 0.8.\n',
        ),
      ),
    ),
    max_output_tokens: v.optional(
      v.pipe(
        v.union([v.pipe(v.number(), v.integer()), v.literal('inf')]),
        v.description(
          'Maximum number of output tokens for a single assistant response,\ninclusive of tool calls. Provide an integer between 1 and 4096 to\nlimit output tokens, or `inf` for the maximum available tokens for a\ngiven model. Defaults to `inf`.\n',
        ),
      ),
    ),
    conversation: v.optional(
      v.pipe(
        v.union([v.string(), v.optional(v.picklist(['auto', 'none']), 'auto')]),
        v.description(
          'Controls which conversation the response is added to. Currently supports\n`auto` and `none`, with `auto` as the default value. The `auto` value\nmeans that the contents of the response will be added to the default\nconversation. Set this to `none` to create an out-of-band response which \nwill not add items to default conversation.\n',
        ),
      ),
    ),
    metadata: v.optional(MetadataSchema),
    prompt: v.optional(PromptSchema),
    input: v.optional(
      v.pipe(
        v.array(RealtimeConversationItemSchema),
        v.description(
          'Input items to include in the prompt for the model. Using this field\ncreates a new context for this Response instead of using the default\nconversation. An empty array `[]` will clear the context for this Response.\nNote that this can include references to items from the default conversation.\n',
        ),
      ),
    ),
  }),
  v.description('Create a new Realtime response with these parameters'),
)

