export const RealtimeResponseSchema = v.pipe(
  v.partial(
    v.object({
      id: v.pipe(
        v.string(),
        v.description('The unique ID of the response, will look like `resp_1234`.'),
      ),
      object: v.pipe(
        v.literal('realtime.response'),
        v.description('The object type, must be `realtime.response`.'),
      ),
      status: v.pipe(
        v.picklist(['completed', 'cancelled', 'failed', 'incomplete', 'in_progress']),
        v.description(
          'The final status of the response (`completed`, `cancelled`, `failed`, or \n`incomplete`, `in_progress`).\n',
        ),
      ),
      status_details: v.pipe(
        v.partial(
          v.object({
            type: v.pipe(
              v.picklist(['completed', 'cancelled', 'failed', 'incomplete']),
              v.description(
                'The type of error that caused the response to fail, corresponding \nwith the `status` field (`completed`, `cancelled`, `incomplete`, \n`failed`).\n',
              ),
            ),
            reason: v.pipe(
              v.picklist([
                'turn_detected',
                'client_cancelled',
                'max_output_tokens',
                'content_filter',
              ]),
              v.description(
                'The reason the Response did not complete. For a `cancelled` Response,  one of `turn_detected` (the server VAD detected a new start of speech)  or `client_cancelled` (the client sent a cancel event). For an  `incomplete` Response, one of `max_output_tokens` or `content_filter`  (the server-side safety filter activated and cut off the response).\n',
              ),
            ),
            error: v.pipe(
              v.partial(
                v.object({
                  type: v.pipe(v.string(), v.description('The type of error.')),
                  code: v.pipe(v.string(), v.description('Error code, if any.')),
                  message: v.pipe(v.string(), v.description('A human-readable error message.')),
                }),
              ),
              v.description(
                'A description of the error that caused the response to fail, \npopulated when the `status` is `failed`.\n',
              ),
            ),
          }),
        ),
        v.description('Additional details about the status.'),
      ),
      output: v.pipe(
        v.array(RealtimeConversationItemSchema),
        v.description('The list of output items generated by the response.'),
      ),
      metadata: MetadataSchema,
      audio: v.pipe(
        v.partial(
          v.object({
            output: v.object({
              format: v.optional(
                v.pipe(
                  RealtimeAudioFormatsSchema,
                  v.description('The format of the output audio.'),
                ),
              ),
              voice: v.pipe(
                v.optional(VoiceIdsSharedSchema, 'alloy'),
                v.description(
                  'The voice the model uses to respond. Voice cannot be changed during the\nsession once the model has responded with audio at least once. Current\nvoice options are `alloy`, `ash`, `ballad`, `coral`, `echo`, `sage`,\n`shimmer`, `verse`, `marin`, and `cedar`. We recommend `marin` and `cedar` for\nbest quality.\n',
                ),
              ),
            }),
          }),
        ),
        v.description('Configuration for audio output.'),
      ),
      usage: v.pipe(
        v.partial(
          v.object({
            total_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description(
                'The total number of tokens in the Response including input and output \ntext and audio tokens.\n',
              ),
            ),
            input_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description(
                'The number of input tokens used in the Response, including text and \naudio tokens.\n',
              ),
            ),
            output_tokens: v.pipe(
              v.pipe(v.number(), v.integer()),
              v.description(
                'The number of output tokens sent in the Response, including text and \naudio tokens.\n',
              ),
            ),
            input_token_details: v.pipe(
              v.partial(
                v.object({
                  cached_tokens: v.pipe(
                    v.pipe(v.number(), v.integer()),
                    v.description('The number of cached tokens used as input for the Response.'),
                  ),
                  text_tokens: v.pipe(
                    v.pipe(v.number(), v.integer()),
                    v.description('The number of text tokens used as input for the Response.'),
                  ),
                  image_tokens: v.pipe(
                    v.pipe(v.number(), v.integer()),
                    v.description('The number of image tokens used as input for the Response.'),
                  ),
                  audio_tokens: v.pipe(
                    v.pipe(v.number(), v.integer()),
                    v.description('The number of audio tokens used as input for the Response.'),
                  ),
                  cached_tokens_details: v.pipe(
                    v.partial(
                      v.object({
                        text_tokens: v.pipe(
                          v.pipe(v.number(), v.integer()),
                          v.description(
                            'The number of cached text tokens used as input for the Response.',
                          ),
                        ),
                        image_tokens: v.pipe(
                          v.pipe(v.number(), v.integer()),
                          v.description(
                            'The number of cached image tokens used as input for the Response.',
                          ),
                        ),
                        audio_tokens: v.pipe(
                          v.pipe(v.number(), v.integer()),
                          v.description(
                            'The number of cached audio tokens used as input for the Response.',
                          ),
                        ),
                      }),
                    ),
                    v.description(
                      'Details about the cached tokens used as input for the Response.',
                    ),
                  ),
                }),
              ),
              v.description(
                'Details about the input tokens used in the Response. Cached tokens are tokens from previous turns in the conversation that are included as context for the current response. Cached tokens here are counted as a subset of input tokens, meaning input tokens will include cached and uncached tokens.',
              ),
            ),
            output_token_details: v.pipe(
              v.partial(
                v.object({
                  text_tokens: v.pipe(
                    v.pipe(v.number(), v.integer()),
                    v.description('The number of text tokens used in the Response.'),
                  ),
                  audio_tokens: v.pipe(
                    v.pipe(v.number(), v.integer()),
                    v.description('The number of audio tokens used in the Response.'),
                  ),
                }),
              ),
              v.description('Details about the output tokens used in the Response.'),
            ),
          }),
        ),
        v.description(
          'Usage statistics for the Response, this will correspond to billing. A \nRealtime API session will maintain a conversation context and append new \nItems to the Conversation, thus output from previous turns (text and \naudio tokens) will become the input for later turns.\n',
        ),
      ),
      conversation_id: v.pipe(
        v.string(),
        v.description(
          'Which conversation the response is added to, determined by the `conversation`\nfield in the `response.create` event. If `auto`, the response will be added to\nthe default conversation and the value of `conversation_id` will be an id like\n`conv_1234`. If `none`, the response will not be added to any conversation and\nthe value of `conversation_id` will be `null`. If responses are being triggered\nautomatically by VAD the response will be added to the default conversation\n',
        ),
      ),
      output_modalities: v.pipe(
        v.array(v.picklist(['text', 'audio'])),
        v.description(
          'The set of modalities the model used to respond, currently the only possible values are\n`[\\"audio\\"]`, `[\\"text\\"]`. Audio output always include a text transcript. Setting the\noutput to mode `text` will disable audio output from the model.\n',
        ),
      ),
      max_output_tokens: v.pipe(
        v.union([v.pipe(v.number(), v.integer()), v.literal('inf')]),
        v.description(
          'Maximum number of output tokens for a single assistant response,\ninclusive of tool calls, that was used in this response.\n',
        ),
      ),
    }),
  ),
  v.description('The response resource.'),
)

export type RealtimeResponse = v.InferOutput<typeof RealtimeResponseSchema>

