export const RealtimeSessionCreateResponseSchema = v.pipe(
  v.partial(
    v.object({
      id: v.pipe(
        v.string(),
        v.description(
          'Unique identifier for the session that looks like `sess_1234567890abcdef`.\n',
        ),
      ),
      object: v.pipe(v.string(), v.description('The object type. Always `realtime.session`.')),
      expires_at: v.pipe(
        v.pipe(v.number(), v.integer()),
        v.description('Expiration timestamp for the session, in seconds since epoch.'),
      ),
      include: v.pipe(
        v.array(v.literal('item.input_audio_transcription.logprobs')),
        v.description(
          'Additional fields to include in server outputs.\n- `item.input_audio_transcription.logprobs`: Include logprobs for input audio transcription.\n',
        ),
      ),
      model: v.pipe(v.string(), v.description('The Realtime model used for this session.')),
      output_modalities: v.pipe(
        v.any(),
        v.description(
          'The set of modalities the model can respond with. To disable audio,\nset this to ["text"].\n',
        ),
      ),
      instructions: v.pipe(
        v.string(),
        v.description(
          'The default system instructions (i.e. system message) prepended to model\ncalls. This field allows the client to guide the model on desired\nresponses. The model can be instructed on response content and format,\n(e.g. "be extremely succinct", "act friendly", "here are examples of good\nresponses") and on audio behavior (e.g. "talk quickly", "inject emotion\ninto your voice", "laugh frequently"). The instructions are not guaranteed\nto be followed by the model, but they provide guidance to the model on the\ndesired behavior.\n\nNote that the server sets default instructions which will be used if this\nfield is not set and are visible in the `session.created` event at the\nstart of the session.\n',
        ),
      ),
      audio: v.pipe(
        v.partial(
          v.object({
            input: v.partial(
              v.object({
                format: RealtimeAudioFormatsSchema,
                transcription: v.pipe(
                  AudioTranscriptionResponseSchema,
                  v.description('Configuration for input audio transcription.\n'),
                ),
                noise_reduction: v.pipe(
                  v.nullable(v.partial(v.object({ type: NoiseReductionTypeSchema }))),
                  v.description('Configuration for input audio noise reduction.\n'),
                ),
                turn_detection: v.pipe(
                  v.nullable(
                    v.partial(
                      v.object({
                        type: v.pipe(
                          v.string(),
                          v.description(
                            'Type of turn detection, only `server_vad` is currently supported.\n',
                          ),
                        ),
                        threshold: v.number(),
                        prefix_padding_ms: v.pipe(v.number(), v.integer()),
                        silence_duration_ms: v.pipe(v.number(), v.integer()),
                      }),
                    ),
                  ),
                  v.description('Configuration for turn detection.\n'),
                ),
              }),
            ),
            output: v.partial(
              v.object({
                format: RealtimeAudioFormatsSchema,
                voice: VoiceIdsSharedSchema,
                speed: v.number(),
              }),
            ),
          }),
        ),
        v.description('Configuration for input and output audio for the session.\n'),
      ),
      tracing: v.pipe(
        v.union([
          v.pipe(
            v.optional(v.literal('auto'), 'auto'),
            v.description('Default tracing mode for the session.\n'),
          ),
          v.pipe(
            v.partial(
              v.object({
                workflow_name: v.pipe(
                  v.string(),
                  v.description(
                    'The name of the workflow to attach to this trace. This is used to\nname the trace in the traces dashboard.\n',
                  ),
                ),
                group_id: v.pipe(
                  v.string(),
                  v.description(
                    'The group id to attach to this trace to enable filtering and\ngrouping in the traces dashboard.\n',
                  ),
                ),
                metadata: v.pipe(
                  v.object({}),
                  v.description(
                    'The arbitrary metadata to attach to this trace to enable\nfiltering in the traces dashboard.\n',
                  ),
                ),
              }),
            ),
            v.description('Granular configuration for tracing.\n'),
          ),
        ]),
        v.description(
          'Configuration options for tracing. Set to null to disable tracing. Once\ntracing is enabled for a session, the configuration cannot be modified.\n\n`auto` will create a trace for the session with default values for the\nworkflow name, group id, and metadata.\n',
        ),
      ),
      turn_detection: v.pipe(
        v.nullable(
          v.partial(
            v.object({
              type: v.pipe(
                v.string(),
                v.description(
                  'Type of turn detection, only `server_vad` is currently supported.\n',
                ),
              ),
              threshold: v.pipe(
                v.number(),
                v.description(
                  'Activation threshold for VAD (0.0 to 1.0), this defaults to 0.5. A\nhigher threshold will require louder audio to activate the model, and\nthus might perform better in noisy environments.\n',
                ),
              ),
              prefix_padding_ms: v.pipe(
                v.pipe(v.number(), v.integer()),
                v.description(
                  'Amount of audio to include before the VAD detected speech (in\nmilliseconds). Defaults to 300ms.\n',
                ),
              ),
              silence_duration_ms: v.pipe(
                v.pipe(v.number(), v.integer()),
                v.description(
                  'Duration of silence to detect speech stop (in milliseconds). Defaults\nto 500ms. With shorter values the model will respond more quickly,\nbut may jump in on short pauses from the user.\n',
                ),
              ),
            }),
          ),
        ),
        v.description(
          'Configuration for turn detection. Can be set to `null` to turn off. Server\nVAD means that the model will detect the start and end of speech based on\naudio volume and respond at the end of user speech.\n',
        ),
      ),
      tools: v.pipe(
        v.array(RealtimeFunctionToolSchema),
        v.description('Tools (functions) available to the model.'),
      ),
      tool_choice: v.pipe(
        v.string(),
        v.description(
          'How the model chooses tools. Options are `auto`, `none`, `required`, or\nspecify a function.\n',
        ),
      ),
      max_output_tokens: v.pipe(
        v.union([v.pipe(v.number(), v.integer()), v.literal('inf')]),
        v.description(
          'Maximum number of output tokens for a single assistant response,\ninclusive of tool calls. Provide an integer between 1 and 4096 to\nlimit output tokens, or `inf` for the maximum available tokens for a\ngiven model. Defaults to `inf`.\n',
        ),
      ),
    }),
  ),
  v.description('A Realtime session configuration object.\n'),
)

