export const ResponseItemListSchema = v.pipe(
  v.object({
    object: v.pipe(
      v.literal('list'),
      v.description('The type of object returned, must be `list`.'),
    ),
    data: v.pipe(
      v.array(ItemResourceSchema),
      v.description('A list of items used to generate this response.'),
    ),
    has_more: v.pipe(v.boolean(), v.description('Whether there are more items available.')),
    first_id: v.pipe(v.string(), v.description('The ID of the first item in the list.')),
    last_id: v.pipe(v.string(), v.description('The ID of the last item in the list.')),
  }),
  v.description('A list of Response items.'),
)

export type ResponseItemList = v.InferOutput<typeof ResponseItemListSchema>

export const ResponseLogProbSchema = v.pipe(
  v.object({
    token: v.pipe(v.string(), v.description('A possible text token.')),
    logprob: v.pipe(v.number(), v.description('The log probability of this token.\n')),
    top_logprobs: v.optional(
      v.pipe(
        v.array(
          v.partial(
            v.object({
              token: v.pipe(v.string(), v.description('A possible text token.')),
              logprob: v.pipe(v.number(), v.description('The log probability of this token.')),
            }),
          ),
        ),
        v.description('The log probabilities of up to 20 of the most likely tokens.\n'),
      ),
    ),
  }),
  v.description(
    'A logprob is the logarithmic probability that the model assigns to producing \na particular token at a given position in the sequence. Less-negative (higher) \nlogprob values indicate greater model confidence in that token choice.\n',
  ),
)

export type ResponseLogProb = v.InferOutput<typeof ResponseLogProbSchema>

