export const RunGraderRequestSchema = v.object({
  grader: v.pipe(
    v.union([
      GraderStringCheckSchema,
      GraderTextSimilaritySchema,
      GraderPythonSchema,
      GraderScoreModelSchema,
      GraderMultiSchema,
    ]),
    v.description('The grader used for the fine-tuning job.'),
  ),
  item: v.optional(
    v.pipe(
      v.object({}),
      v.description(
        'The dataset item provided to the grader. This will be used to populate\nthe `item` namespace. See [the guide](https://developers.openai.com/api/docs/guides/graders) for more details.\n',
      ),
    ),
  ),
  model_sample: v.pipe(
    v.string(),
    v.description(
      'The model sample to be evaluated. This value will be used to populate\nthe `sample` namespace. See [the guide](https://developers.openai.com/api/docs/guides/graders) for more details.\nThe `output_json` variable will be populated if the model sample is a\nvalid JSON string.\n',
    ),
  ),
})

export type RunGraderRequest = v.InferOutput<typeof RunGraderRequestSchema>

export const RunGraderResponseSchema = v.object({
  reward: v.number(),
  metadata: v.object({
    name: v.string(),
    type: v.string(),
    errors: v.object({
      formula_parse_error: v.boolean(),
      sample_parse_error: v.boolean(),
      truncated_observation_error: v.boolean(),
      unresponsive_reward_error: v.boolean(),
      invalid_variable_error: v.boolean(),
      other_error: v.boolean(),
      python_grader_server_error: v.boolean(),
      python_grader_server_error_type: v.union([v.string(), v.nullable(v.null())]),
      python_grader_runtime_error: v.boolean(),
      python_grader_runtime_error_details: v.union([v.string(), v.nullable(v.null())]),
      model_grader_server_error: v.boolean(),
      model_grader_refusal_error: v.boolean(),
      model_grader_parse_error: v.boolean(),
      model_grader_server_error_details: v.union([v.string(), v.nullable(v.null())]),
    }),
    execution_time: v.number(),
    scores: v.record(v.string(), v.any()),
    token_usage: v.union([
      v.object({
        prompt_tokens: v.pipe(v.number(), v.integer()),
        total_tokens: v.pipe(v.number(), v.integer()),
        completion_tokens: v.optional(
          v.union([v.pipe(v.number(), v.integer()), v.nullable(v.null())]),
        ),
        cached_tokens: v.optional(v.union([v.pipe(v.number(), v.integer()), v.nullable(v.null())])),
      }),
      v.nullable(v.null()),
    ]),
    sampled_model_name: v.union([v.string(), v.nullable(v.null())]),
  }),
  sub_rewards: v.record(v.string(), v.any()),
  model_grader_token_usage_per_model: v.record(v.string(), v.any()),
})

export type RunGraderResponse = v.InferOutput<typeof RunGraderResponseSchema>

