export const AttachmentSchema = v.pipe(
  v.object({
    type: v.pipe(AttachmentTypeSchema, v.description('Attachment discriminator.')),
    id: v.pipe(v.string(), v.description('Identifier for the attachment.')),
    name: v.pipe(v.string(), v.description('Original display name for the attachment.')),
    mime_type: v.pipe(v.string(), v.description('MIME type of the attachment.')),
    preview_url: v.union([
      v.pipe(
        v.pipe(v.string(), v.url()),
        v.description('Preview URL for rendering the attachment inline.'),
      ),
      v.nullable(v.null()),
    ]),
  }),
  v.description('Attachment metadata included on thread items.'),
)

export type Attachment = v.InferOutput<typeof AttachmentSchema>

export const ToolChoiceSchema = v.pipe(
  v.object({ id: v.pipe(v.string(), v.description('Identifier of the requested tool.')) }),
  v.description('Tool selection that the assistant should honor when executing the item.'),
)

export type ToolChoice = v.InferOutput<typeof ToolChoiceSchema>

export const InferenceOptionsSchema = v.pipe(
  v.object({
    tool_choice: v.union([
      v.pipe(
        ToolChoiceSchema,
        v.description(
          'Preferred tool to invoke. Defaults to null when ChatKit should auto-select.',
        ),
      ),
      v.nullable(v.null()),
    ]),
    model: v.union([
      v.pipe(
        v.string(),
        v.description(
          'Model name that generated the response. Defaults to null when using the session default.',
        ),
      ),
      v.nullable(v.null()),
    ]),
  }),
  v.description('Model and tool overrides applied when generating the assistant response.'),
)

export type InferenceOptions = v.InferOutput<typeof InferenceOptionsSchema>

export const UserMessageItemSchema = v.pipe(
  v.object({
    id: v.pipe(v.string(), v.description('Identifier of the thread item.')),
    object: v.pipe(
      v.optional(v.literal('chatkit.thread_item'), 'chatkit.thread_item'),
      v.description('Type discriminator that is always `chatkit.thread_item`.'),
    ),
    created_at: v.pipe(
      v.pipe(v.number(), v.integer()),
      v.description('Unix timestamp (in seconds) for when the item was created.'),
    ),
    thread_id: v.pipe(v.string(), v.description('Identifier of the parent thread.')),
    type: v.optional(v.literal('chatkit.user_message'), 'chatkit.user_message'),
    content: v.pipe(
      v.array(
        v.pipe(
          v.union([UserMessageInputTextSchema, UserMessageQuotedTextSchema]),
          v.description('Content blocks that comprise a user message.'),
        ),
      ),
      v.description('Ordered content elements supplied by the user.'),
    ),
    attachments: v.pipe(
      v.array(AttachmentSchema),
      v.description('Attachments associated with the user message. Defaults to an empty list.'),
    ),
    inference_options: v.union([
      v.pipe(
        InferenceOptionsSchema,
        v.description('Inference overrides applied to the message. Defaults to null when unset.'),
      ),
      v.nullable(v.null()),
    ]),
  }),
  v.description('User-authored messages within a thread.'),
)

export type UserMessageItem = v.InferOutput<typeof UserMessageItemSchema>

