export const DecisionInputTextSchema = v.strictObject({
  type: v.optional(v.literal('input_text'), 'input_text'),
  text: v.pipe(v.string(), v.minCodePoints(0), v.maxCodePoints(10485760)),
  prompt_cache_breakpoint: v.optional(
    v.pipe(
      v.nullable(
        v.strictObject({
          mode: v.pipe(
            v.optional(v.literal('explicit'), 'explicit'),
            v.description('The breakpoint mode. Always `explicit`.'),
          ),
        }),
      ),
      v.description(
        "Marks the exact end of a reusable prompt prefix. The breakpoint inherits its TTL from the request's `prompt_cache_options.ttl`; the boundary is not rounded to a token block.",
      ),
    ),
  ),
})

export type DecisionInputText = v.InferOutput<typeof DecisionInputTextSchema>

export const ImageDetailParamSchema = v.picklist(['low', 'high', 'auto', 'original'])

