export const CommandExecutionItemResourceSchema = v.pipe(
  v.strictObject({
    type: v.pipe(
      v.optional(v.literal('command_execution'), 'command_execution'),
      v.description('The item type. Always `command_execution`.'),
    ),
    id: v.pipe(
      v.pipe(v.string(), v.minCodePoints(0)),
      v.description('The ID of the command execution item.'),
    ),
    turn_id: v.pipe(
      v.pipe(v.string(), v.minCodePoints(0)),
      v.description('The ID of the turn that contains this item.'),
    ),
    command: v.pipe(
      v.pipe(v.string(), v.minCodePoints(0)),
      v.description('The command that was executed.'),
    ),
    cwd: v.pipe(
      v.nullable(v.pipe(v.string(), v.minCodePoints(0))),
      v.description('The working directory used to execute the command.'),
    ),
    status: v.pipe(
      FunctionCallStatusResourceSchema,
      v.description('The status of the command execution.'),
    ),
    output: v.pipe(
      v.nullable(v.pipe(v.string(), v.minCodePoints(0))),
      v.description('The command output, if available.'),
    ),
    exit_code: v.pipe(
      v.nullable(
        v.pipe(
          v.union([
            v.bigint(),
            v.pipe(v.number(), v.integer()),
            v.pipe(v.string(), v.regex(/^-?\d+$/)),
          ]),
          v.transform((input) => BigInt(input)),
          v.minValue(-9223372036854775808n),
          v.maxValue(9223372036854775807n),
        ),
      ),
      v.description('The process exit code, if the command completed.'),
    ),
    duration_ms: v.pipe(
      v.nullable(
        v.pipe(
          v.union([
            v.bigint(),
            v.pipe(v.number(), v.integer()),
            v.pipe(v.string(), v.regex(/^-?\d+$/)),
          ]),
          v.transform((input) => BigInt(input)),
          v.minValue(-9223372036854775808n),
          v.maxValue(9223372036854775807n),
        ),
      ),
      v.description('The command duration in milliseconds.'),
    ),
  }),
  v.description('A command execution produced by the agent.'),
)

