export const EnvironmentTemplateResourceSchema = v.pipe(
  v.strictObject({
    id: v.pipe(
      v.pipe(v.string(), v.minCodePoints(0)),
      v.description('The ID of the reusable environment template.'),
    ),
    name: v.pipe(
      v.nullable(v.pipe(v.string(), v.minCodePoints(0))),
      v.description('An optional human-readable display name for the template.'),
    ),
    object: v.pipe(
      v.optional(v.literal('agent.environment.template'), 'agent.environment.template'),
      v.description('The object type. Always `agent.environment.template`.'),
    ),
    created_at: v.pipe(
      v.pipe(
        v.union([
          v.bigint(),
          v.pipe(v.number(), v.integer()),
          v.pipe(v.string(), v.regex(/^-?\d+$/)),
        ]),
        v.transform((input) => BigInt(input)),
        v.minValue(-9223372036854775808n),
        v.maxValue(9223372036854775807n),
      ),
      v.description('The Unix timestamp, in seconds, when the template was created.'),
    ),
    updated_at: v.pipe(
      v.pipe(
        v.union([
          v.bigint(),
          v.pipe(v.number(), v.integer()),
          v.pipe(v.string(), v.regex(/^-?\d+$/)),
        ]),
        v.transform((input) => BigInt(input)),
        v.minValue(-9223372036854775808n),
        v.maxValue(9223372036854775807n),
      ),
      v.description('The Unix timestamp, in seconds, when the template was last updated.'),
    ),
    packages: v.pipe(
      EnvironmentPackagesResourceSchema,
      v.description('Packages installed in each fresh OpenAI-hosted environment.'),
    ),
    network: v.pipe(
      NetworkPolicyResourceSchema,
      v.description('Runtime network access for each OpenAI-hosted environment.'),
    ),
    desktop: v.pipe(
      DesktopResourceSchema,
      v.description('Desktop configuration for each OpenAI-hosted environment.'),
    ),
    capability_directories: v.pipe(
      v.pipe(v.array(v.pipe(v.string(), v.minCodePoints(0))), v.minLength(0), v.maxLength(2000)),
      v.description('Directories that expose capabilities to the agent.'),
    ),
    skills: v.pipe(
      v.pipe(v.array(HostedTemplateSkillResourceSchema), v.minLength(0), v.maxLength(200)),
      v.description('Safe skill metadata, preserving unresolved version selectors.'),
    ),
    plugins: v.pipe(
      v.pipe(v.array(HostedPluginResourceSchema), v.minLength(0), v.maxLength(32)),
      v.description('Safe plugin metadata, excluding inline archive contents.'),
    ),
    files: v.pipe(
      v.pipe(v.array(HostedTemplateFileResourceSchema), v.minLength(0), v.maxLength(50)),
      v.description('Safe file metadata, excluding contents and session-scoped file IDs.'),
    ),
  }),
  v.description(
    'Reusable configuration that provisions a fresh OpenAI-hosted environment for each session.',
  ),
)

