export const BetaResponseSteerErrorCodeSchema = v.pipe(
  v.union([
    v.picklist([
      'response_not_found',
      'invalid_input',
      'steering_not_supported',
      'too_many_pending_steers',
      'response_already_completed',
      'response_not_active',
      'successor_creation_failed',
    ]),
    v.string(),
  ]),
  v.description(
    'A machine-readable steering error code. Clients should handle unknown\nvalues because additional codes may be introduced. Known values include:\n- `response_not_found`: The target response is not available on this connection.\n- `invalid_input`: The event or input failed validation.\n- `steering_not_supported`: The model or response execution mode does not support steering.\n- `too_many_pending_steers`: Too much steering input is pending for the response.\n- `response_already_completed`: The response completed and is no longer accepting steering input.\n- `response_not_active`: The response is no longer accepting steering input.\n- `successor_creation_failed`: The successor response could not be created.\n',
  ),
)

export type BetaResponseSteerErrorCode = v.InferOutput<typeof BetaResponseSteerErrorCodeSchema>

